#if defined(__APPLE__)
bool glossFieldVectorMatchesSize(const std::vector<float>& values,
                                 size_t expectedSize,
                                 const char* label,
                                 std::string* reason) {
  if (values.size() == expectedSize) return true;
  if (reason) {
    std::ostringstream os;
    os << label << " size mismatch expected=" << expectedSize << " actual=" << values.size();
    *reason = os.str();
  }
  return false;
}

bool glossFieldVectorFinite(const std::vector<float>& values,
                            const char* label,
                            std::string* reason) {
  for (size_t i = 0; i < values.size(); ++i) {
    if (std::isfinite(values[i])) continue;
    if (reason) {
      std::ostringstream os;
      os << label << " contains non-finite value at " << i;
      *reason = os.str();
    }
    return false;
  }
  return true;
}

bool validateGlossFieldResult(const ChromaspaceMetal::GlossFieldResult& result,
                              std::string* reason) {
  if (result.gridWidth <= 0 || result.gridHeight <= 0) {
    if (reason) *reason = "invalid grid dimensions";
    return false;
  }
  const size_t cellCount = static_cast<size_t>(result.gridWidth) * static_cast<size_t>(result.gridHeight);
  if (!glossFieldVectorMatchesSize(result.occupancy, cellCount, "occupancy", reason) ||
      !glossFieldVectorMatchesSize(result.meanRgb, cellCount * 3u, "meanRgb", reason) ||
      !glossFieldVectorMatchesSize(result.carrierY, cellCount, "carrierY", reason) ||
      !glossFieldVectorMatchesSize(result.carrierMax, cellCount, "carrierMax", reason) ||
      !glossFieldVectorMatchesSize(result.carrierMin, cellCount, "carrierMin", reason) ||
      !glossFieldVectorMatchesSize(result.neutrality, cellCount, "neutrality", reason) ||
      !glossFieldVectorMatchesSize(result.body, cellCount, "body", reason) ||
      !glossFieldVectorMatchesSize(result.signal, cellCount, "signal", reason) ||
      !glossFieldVectorMatchesSize(result.positive, cellCount, "positive", reason) ||
      !glossFieldVectorMatchesSize(result.negative, cellCount, "negative", reason) ||
      !glossFieldVectorMatchesSize(result.boundary, cellCount, "boundary", reason) ||
      !glossFieldVectorMatchesSize(result.congruence, cellCount, "congruence", reason) ||
      !glossFieldVectorMatchesSize(result.confidence, cellCount, "confidence", reason)) {
    return false;
  }
  if (!glossFieldVectorFinite(result.occupancy, "occupancy", reason) ||
      !glossFieldVectorFinite(result.meanRgb, "meanRgb", reason) ||
      !glossFieldVectorFinite(result.carrierY, "carrierY", reason) ||
      !glossFieldVectorFinite(result.carrierMax, "carrierMax", reason) ||
      !glossFieldVectorFinite(result.carrierMin, "carrierMin", reason) ||
      !glossFieldVectorFinite(result.neutrality, "neutrality", reason) ||
      !glossFieldVectorFinite(result.body, "body", reason) ||
      !glossFieldVectorFinite(result.signal, "signal", reason) ||
      !glossFieldVectorFinite(result.positive, "positive", reason) ||
      !glossFieldVectorFinite(result.negative, "negative", reason) ||
      !glossFieldVectorFinite(result.boundary, "boundary", reason) ||
      !glossFieldVectorFinite(result.congruence, "congruence", reason) ||
      !glossFieldVectorFinite(result.confidence, "confidence", reason)) {
    return false;
  }
  const float occupancyMax = result.occupancy.empty() ? 0.0f
                                                      : *std::max_element(result.occupancy.begin(), result.occupancy.end());
  if (!(occupancyMax > 0.0f)) {
    if (reason) *reason = "occupancy grid is empty";
    return false;
  }
  return true;
}

bool runViewerMetalGlossFieldStartupSelfTest(std::string* reason) {
  const std::vector<float> packedPoints = {
      0.20f, 0.20f, 0.0f, 0.14f, 0.14f, 0.14f,
      0.26f, 0.22f, 0.0f, 0.52f, 0.48f, 0.47f,
      0.62f, 0.58f, 0.0f, 0.18f, 0.24f, 0.42f,
      0.66f, 0.60f, 0.0f, 0.74f, 0.70f, 0.68f,
      0.68f, 0.63f, 0.0f, 0.10f, 0.12f, 0.18f,
      0.78f, 0.32f, 0.0f, 0.64f, 0.32f, 0.18f,
      0.82f, 0.36f, 0.0f, 0.88f, 0.86f, 0.80f,
      0.38f, 0.74f, 0.0f, 0.30f, 0.30f, 0.30f
  };
  ChromaspaceMetal::GlossFieldRequest request{};
  request.gridWidth = 12;
  request.gridHeight = 10;
  request.showOverflow = 0;
  request.neighborhoodChoice = 1;
  ChromaspaceMetal::GlossFieldResult result{};
  std::string localReason;
  if (!ChromaspaceMetal::buildGlossField(request, packedPoints, true, &result, &localReason)) {
    if (reason) *reason = localReason.empty() ? std::string("Metal gloss-field startup dispatch failed.") : localReason;
    return false;
  }
  if (!validateGlossFieldResult(result, &localReason)) {
    if (reason) *reason = localReason.empty() ? std::string("Metal gloss-field startup validation failed.") : localReason;
    return false;
  }
  if (reason) *reason = "validated";
  return true;
}

void setIdentityMatrix16(float values[16]) {
  if (!values) return;
  for (int i = 0; i < 16; ++i) values[i] = 0.0f;
  values[0] = 1.0f;
  values[5] = 1.0f;
  values[10] = 1.0f;
  values[15] = 1.0f;
}

bool runViewerMetalResidentChainStartupSelfTest(std::string* reason) {
  auto fail = [&](const std::string& stage, const std::string& detail) {
    if (reason) {
      *reason = stage + (detail.empty() ? std::string() : (std::string(":") + detail));
    }
    return false;
  };

  ChromaspaceMetal::PlotSurface sourceSurface{};
  ChromaspaceMetal::PlotSurface histogramSurface{};
  ChromaspaceMetal::PlotSurface fieldSurface{};
  ChromaspaceMetal::PlotSurface projectionSurface{};
  ChromaspaceMetal::GlossFieldCache glossCache{};
  GLuint importedTexture = 0;
  std::string localReason;

  const auto releaseAll = [&]() {
    if (importedTexture != 0) {
      glDeleteTextures(1, &importedTexture);
      importedTexture = 0;
    }
    ChromaspaceMetal::releaseGlossFieldCache(&glossCache);
    if (projectionSurface.surfaceId != 0) ChromaspaceMetal::releasePlotSurface(projectionSurface.surfaceId);
    if (fieldSurface.surfaceId != 0) ChromaspaceMetal::releasePlotSurface(fieldSurface.surfaceId);
    if (histogramSurface.surfaceId != 0) ChromaspaceMetal::releasePlotSurface(histogramSurface.surfaceId);
    if (sourceSurface.surfaceId != 0) ChromaspaceMetal::releasePlotSurface(sourceSurface.surfaceId);
  };

  if (!ChromaspaceMetal::createPlotSurface(16, 16, 0, &sourceSurface, &localReason)) {
    releaseAll();
    return fail("source-surface", localReason);
  }
  if (!ChromaspaceMetal::clearPlotSurface(sourceSurface.surfaceId,
                                          sourceSurface.width,
                                          sourceSurface.height,
                                          sourceSurface.pixelFormat,
                                          0.36f,
                                          0.42f,
                                          0.50f,
                                          1.0f,
                                          &localReason)) {
    releaseAll();
    return fail("source-surface-clear", localReason);
  }

  ChromaspaceMetal::RasterSourceRequest rasterRequest{};
  rasterRequest.pointCount = sourceSurface.width * sourceSurface.height;
  rasterRequest.basePointCount = rasterRequest.pointCount;
  rasterRequest.sourceWidth = sourceSurface.width;
  rasterRequest.sourceHeight = sourceSurface.height;
  rasterRequest.sampleStride = 1;
  rasterRequest.sampleCountX = sourceSurface.width;
  rasterRequest.pixelFormat = sourceSurface.pixelFormat;
  rasterRequest.sourceAspect = 1.0f;
  rasterRequest.pointAlphaScale = 1.0f;
  rasterRequest.colorSaturation = 1.0f;

  ChromaspaceMetal::ScopeRangeRequest rangeRequest{};
  rangeRequest.pointCount = rasterRequest.pointCount;
  rangeRequest.waveform = 1;
  rangeRequest.scopeMode = 0;
  rangeRequest.includeRed = 1;
  rangeRequest.includeGreen = 1;
  rangeRequest.includeBlue = 1;
  rangeRequest.includeLuma = 0;
  rangeRequest.includeOverflow = 1;
  ChromaspaceMetal::ScopeRangeResult rangeResult{};
  if (!ChromaspaceMetal::buildScopeRangeFromIOSurface(rasterRequest,
                                                       rangeRequest,
                                                       sourceSurface.surfaceId,
                                                       sourceSurface.width,
                                                       sourceSurface.height,
                                                       sourceSurface.pixelFormat,
                                                       &rangeResult,
                                                       &localReason)) {
    releaseAll();
    return fail("scope-range", localReason);
  }
  if (rangeResult.validCount == 0u || !std::isfinite(rangeResult.minValue) ||
      !std::isfinite(rangeResult.maxValue)) {
    releaseAll();
    return fail("scope-range", "invalid-result");
  }

  if (!ChromaspaceMetal::createPlotSurface(64, 48, 0, &histogramSurface, &localReason)) {
    releaseAll();
    return fail("histogram-surface", localReason);
  }
  ChromaspaceMetal::HistogramSurfaceRequest histogramRequest{};
  histogramRequest.pointCount = rasterRequest.pointCount;
  histogramRequest.width = histogramSurface.width;
  histogramRequest.height = histogramSurface.height;
  histogramRequest.rangeMin = 0.0f;
  histogramRequest.invRange = 1.0f;
  if (!ChromaspaceMetal::renderHistogramSurfaceFromIOSurface(rasterRequest,
                                                             histogramRequest,
                                                             sourceSurface.surfaceId,
                                                             sourceSurface.width,
                                                             sourceSurface.height,
                                                             sourceSurface.pixelFormat,
                                                             histogramSurface.surfaceId,
                                                             histogramSurface.width,
                                                             histogramSurface.height,
                                                             histogramSurface.pixelFormat,
                                                             &localReason)) {
    releaseAll();
    return fail("histogram-render", localReason);
  }

  ChromaspaceMetal::GlossFieldRequest fieldRequest{};
  fieldRequest.gridWidth = 8;
  fieldRequest.gridHeight = 8;
  fieldRequest.showOverflow = 0;
  fieldRequest.neighborhoodChoice = 1;
  if (!ChromaspaceMetal::buildGlossFieldFromIOSurface(&glossCache,
                                                      rasterRequest,
                                                      fieldRequest,
                                                      sourceSurface.surfaceId,
                                                      sourceSurface.width,
                                                      sourceSurface.height,
                                                      sourceSurface.pixelFormat,
                                                      1u,
                                                      &localReason)) {
    releaseAll();
    return fail("gloss-field-cache", localReason);
  }

  if (!ChromaspaceMetal::createPlotSurface(64, 64, 0, &fieldSurface, &localReason)) {
    releaseAll();
    return fail("gloss-field-surface", localReason);
  }
  ChromaspaceMetal::GlossFieldSurfaceRequest fieldSurfaceRequest{};
  fieldSurfaceRequest.width = fieldSurface.width;
  fieldSurfaceRequest.height = fieldSurface.height;
  fieldSurfaceRequest.algorithm = 1;
  if (!ChromaspaceMetal::renderGlossFieldSurfaceFromCache(glossCache,
                                                          fieldSurfaceRequest,
                                                          fieldSurface.surfaceId,
                                                          fieldSurface.width,
                                                          fieldSurface.height,
                                                          fieldSurface.pixelFormat,
                                                          &localReason)) {
    releaseAll();
    return fail("gloss-field-surface-render", localReason);
  }

  if (!ChromaspaceMetal::createPlotSurface(64, 64, 0, &projectionSurface, &localReason)) {
    releaseAll();
    return fail("gloss-projection-surface", localReason);
  }
  ChromaspaceMetal::GlossProjectionSurfaceRequest projectionRequest{};
  projectionRequest.width = projectionSurface.width;
  projectionRequest.height = projectionSurface.height;
  projectionRequest.algorithm = 1;
  projectionRequest.sourceAspect = 1.0f;
  projectionRequest.pointRadiusPixels = 1.5f;
  setIdentityMatrix16(projectionRequest.modelView);
  setIdentityMatrix16(projectionRequest.projection);
  if (!ChromaspaceMetal::renderGlossProjectionSurfaceFromCache(glossCache,
                                                               projectionRequest,
                                                               projectionSurface.surfaceId,
                                                               projectionSurface.width,
                                                               projectionSurface.height,
                                                               projectionSurface.pixelFormat,
                                                               &localReason)) {
    releaseAll();
    return fail("gloss-projection-surface-render", localReason);
  }

  glGenTextures(1, &importedTexture);
  if (importedTexture == 0) {
    releaseAll();
    return fail("opengl-import", "texture-allocation");
  }
  if (!ChromaspaceMetal::bindIOSurfaceToOpenGLTexture(projectionSurface.surfaceId,
                                                      projectionSurface.width,
                                                      projectionSurface.height,
                                                      projectionSurface.pixelFormat,
                                                      importedTexture,
                                                      &localReason)) {
    releaseAll();
    return fail("opengl-import", localReason);
  }
  glBindTexture(GL_TEXTURE_RECTANGLE, importedTexture);
  const GLenum importGlError = glGetError();
  glBindTexture(GL_TEXTURE_RECTANGLE, 0);
  if (importGlError != GL_NO_ERROR) {
    releaseAll();
    std::ostringstream os;
    os << "gl-error-" << static_cast<unsigned int>(importGlError);
    return fail("opengl-import-bind", os.str());
  }

  releaseAll();
  if (reason) *reason = "resident-iosurface-chain-validated";
  return true;
}
#endif

bool ensurePointBufferCacheUploaded(const MeshData& mesh, PointBufferCache* cache) {
  if (!cache) return false;
  const ViewerGlBufferApi& api = viewerGlBufferApi();
  if (!api.available || mesh.pointVerts.empty() || mesh.pointColors.empty()) return false;
  if (cache->uploadedSerial == mesh.serial && cache->verts != 0 && cache->colors != 0) return true;
  if (cache->verts == 0) api.genBuffers(1, &cache->verts);
  if (cache->colors == 0) api.genBuffers(1, &cache->colors);
  if (cache->verts == 0 || cache->colors == 0) return false;
  api.bindBuffer(GL_ARRAY_BUFFER, cache->verts);
  api.bufferData(GL_ARRAY_BUFFER,
                 static_cast<ViewerGLsizeiptr>(mesh.pointVerts.size() * sizeof(float)),
                 mesh.pointVerts.data(),
                 GL_DYNAMIC_DRAW);
  api.bindBuffer(GL_ARRAY_BUFFER, cache->colors);
  api.bufferData(GL_ARRAY_BUFFER,
                 static_cast<ViewerGLsizeiptr>(mesh.pointColors.size() * sizeof(float)),
                 mesh.pointColors.data(),
                 GL_DYNAMIC_DRAW);
  api.bindBuffer(GL_ARRAY_BUFFER, 0);
  cache->uploadedSerial = mesh.serial;
  cache->pointCount = mesh.pointCount;
  return true;
}

uint64_t floatSampleSignature(const float* values, size_t count) {
  if (!values || count == 0) return 0;
  uint64_t hash = 1469598103934665603ull;
  for (size_t i = 0; i < count; ++i) {
    uint32_t bits = 0;
    static_assert(sizeof(bits) == sizeof(values[i]), "float bit size mismatch");
    std::memcpy(&bits, &values[i], sizeof(bits));
    hash ^= static_cast<uint64_t>(bits);
    hash *= 1099511628211ull;
  }
  return hash;
}

uint64_t vectorSampleSignature(const std::vector<float>& values, size_t maxCount) {
  return floatSampleSignature(values.data(), std::min(values.size(), maxCount));
}

std::vector<float> gpuBufferSampleValues(GLuint bufferId, size_t floatCount) {
  const ViewerGlBufferApi& api = viewerGlBufferApi();
  if (!api.available || api.getBufferSubData == nullptr || bufferId == 0 || floatCount == 0) return {};
  std::vector<float> sample(floatCount, 0.0f);
  api.bindBuffer(GL_ARRAY_BUFFER, bufferId);
  api.getBufferSubData(GL_ARRAY_BUFFER, 0, static_cast<ViewerGLsizeiptr>(floatCount * sizeof(float)), sample.data());
  api.bindBuffer(GL_ARRAY_BUFFER, 0);
  return sample;
}

bool sampledFloatsNear(const std::vector<float>& cpu, const std::vector<float>& gpu, float epsilon) {
  if (cpu.size() != gpu.size() || cpu.empty()) return false;
  for (size_t i = 0; i < cpu.size(); ++i) {
    if (std::fabs(cpu[i] - gpu[i]) > epsilon) return false;
  }
  return true;
}

uint32_t orderedUintFromFloat(float value) {
  uint32_t bits = 0u;
  std::memcpy(&bits, &value, sizeof(bits));
  return (bits & 0x80000000u) ? ~bits : (bits ^ 0x80000000u);
}

float floatFromOrderedUint(uint32_t ordered) {
  const uint32_t bits = (ordered & 0x80000000u) ? (ordered ^ 0x80000000u) : ~ordered;
  float value = 0.0f;
  std::memcpy(&value, &bits, sizeof(value));
  return value;
}

void logParityCheckResult(bool enabled, const std::string& label, bool ok, const std::string& detail) {
  if (!enabled) return;
  logViewerDiagnostic(true, std::string("Parity ") + label + ": " + (ok ? "ok" : "mismatch") + " " + detail);
}

std::string pointDrawSourceLabel(bool useInputCudaBuffers,
                                 bool useInputComputeBuffers,
                                 bool usePointBuffers,
                                 bool useSampledCudaBuffers,
                                 bool useSampledComputeBuffers,
                                 bool useSampledCpuArrays,
                                 bool hasCpuArrays) {
  if (useSampledCudaBuffers) return "cuda-sampled";
  if (useSampledComputeBuffers) return "gl-sampled";
  if (useSampledCpuArrays) return "cpu-sampled-array";
  if (useInputCudaBuffers) return "cuda-compute-input";
  if (useInputComputeBuffers) return "gl-compute-input";
  if (usePointBuffers) return "gl-buffer";
  if (hasCpuArrays) return "cpu-array";
  return "none";
}

