      request.identityCubeAppendY1 = cubeAppend.y1;
      request.identityCubeAppendY2 = cubeAppend.y2;
      request.identityCubeAppendRowStep = cubeAppend.rowStep;
      request.identityCubeAppendXStep = cubeAppend.xStep;
