        if (stroke.points.size() < 3 || strokeIndex >= 16 || pointIndex >= 256) continue;
        const int available = 256 - pointIndex;
        const int count = std::min<int>(available, static_cast<int>(stroke.points.size()));
        if (count < 3) break;
