PlotWindowState* plotWindowById(AppState* app, int id) {
  if (!app) return nullptr;
  for (auto& window : app->plotWindows) {
    if (window.windowId == id) return &window;
  }
  return nullptr;
}

const PlotWindowState* plotWindowById(const AppState& app, int id) {
  for (const auto& window : app.plotWindows) {
    if (window.windowId == id) return &window;
  }
  return nullptr;
}

PlotWindowState* focusedPlotWindow(AppState* app) {
  if (!app) return nullptr;
  if (auto* window = plotWindowById(app, app->focusedPlotWindowId)) return window;
  return app->plotWindows.empty() ? nullptr : &app->plotWindows.front();
}

const PlotWindowState* focusedPlotWindow(const AppState& app) {
  if (const auto* window = plotWindowById(app, app.focusedPlotWindowId)) return window;
  return app.plotWindows.empty() ? nullptr : &app.plotWindows.front();
}

bool plotWindowIsSourceSignal(const PlotWindowState& window) {
  return window.viewState.plotModel == ChromaspaceViewer::kPlotModelSourceSignal;
}

bool plotWindowIsTemporarySourceSignalLassoSurface(const PlotWindowState& window) {
  return plotWindowIsSourceSignal(window) && window.sourceSignalTemporaryLassoSurface;
}

void clearChromaticityHudChoiceAnchor(AppState* app);

PlotWindowState* effectiveSettingsPlotWindow(AppState* app) {
  if (!app) return nullptr;
  PlotWindowState* focused = focusedPlotWindow(app);
  if (focused && plotWindowIsTemporarySourceSignalLassoSurface(*focused)) {
    if (PlotWindowState* owner = plotWindowById(app, focused->sourceSignalDockOwnerWindowId);
        owner && !plotWindowIsSourceSignal(*owner)) {
      return owner;
    }
    if (PlotWindowState* target = plotWindowById(app, app->viewerLassoTargetWindowId);
        target && !plotWindowIsSourceSignal(*target)) {
      return target;
    }
  }
  return focused;
}

const PlotWindowState* effectiveSettingsPlotWindow(const AppState& app) {
  const PlotWindowState* focused = focusedPlotWindow(app);
  if (focused && plotWindowIsTemporarySourceSignalLassoSurface(*focused)) {
    if (const PlotWindowState* owner = plotWindowById(app, focused->sourceSignalDockOwnerWindowId);
        owner && !plotWindowIsSourceSignal(*owner)) {
      return owner;
    }
    if (const PlotWindowState* target = plotWindowById(app, app.viewerLassoTargetWindowId);
        target && !plotWindowIsSourceSignal(*target)) {
      return target;
    }
  }
  return focused;
}

bool focusedPlotWindowIsGlossView(const AppState& app) {
  if (const PlotWindowState* window = effectiveSettingsPlotWindow(app)) {
    return window->viewState.plotModel == ChromaspaceViewer::kPlotModelGlossView;
  }
  return isGlossViewPlotModeString(app.plotMode);
}

void captureFocusedPlotWindowFromApp(AppState* app) {
  if (!app) return;
  if (auto* window = effectiveSettingsPlotWindow(app)) {
    window->viewState = viewerStateWithModelCapabilities(app->viewerState);
    window->camera = app->cam;
    window->selected = true;
  }
}

ChromaspaceViewer::ViewerRuntimeState focusedPlotPresetState(AppState* app) {
  if (!app) return ChromaspaceViewer::ViewerRuntimeState{};
  if (auto* window = effectiveSettingsPlotWindow(app)) {
    // The focused/settings window is mirrored in app->viewerState while menu
    // edits are live. Use that mirror for the focused slot, then copy it back
    // into the window before preset serialization. Non-focused slots keep their
    // own PlotWindowState::viewState.
    auto state = viewerStateWithModelCapabilities(app->viewerState);
    app->viewerState = state;
    app->plotMode = ChromaspaceViewer::plotModeForModel(state.plotModel);
    window->viewState = state;
    return state;
  }
  return viewerStateWithModelCapabilities(app->viewerState);
}

void snapshotFocusedPlotWindowForPresetSerialization(AppState* app) {
  if (!app) return;
  auto state = focusedPlotPresetState(app);
  if (auto* window = effectiveSettingsPlotWindow(app)) {
    // The focused window owns its slot/model identity for both Plot Presets and
    // Layout Presets. Only the camera is copied from AppState here because orbit
    // interaction is staged live in app->cam until the end-of-frame capture.
    window->viewState = viewerStateWithModelCapabilities(state);
    window->camera = app->cam;
    window->selected = true;
  }
}

void applySettingsStateToAppRuntime(AppState* app,
                                    const ChromaspaceViewer::ViewerRuntimeState& state,
                                    const CameraState* camera = nullptr) {
  if (!app) return;
  app->viewerState = viewerStateWithModelCapabilities(state);
  app->plotMode = ChromaspaceViewer::plotModeForModel(app->viewerState.plotModel);
  app->circularHsl = app->viewerState.circularHsl;
  app->circularHsv = app->viewerState.circularHsv;
  app->keepOnTop = app->viewerState.keepOnTop;
  app->readGrayRamp = app->viewerState.readGrayRamp;
  app->readIdentityPlot = app->viewerState.readIdentityPlot;
  app->isolateIdentityData = app->viewerState.isolateIdentityData;
  app->excludeIdentityData = app->viewerState.excludeIdentityData;
  app->identityReadResolution = app->viewerState.identityReadResolution;
  if (camera) app->cam = *camera;
}

void applyPlotWindowToApp(AppState* app, const PlotWindowState& window) {
  if (!app) return;
  app->focusedPlotWindowId = window.windowId;
  const PlotWindowState* settingsWindow = &window;
  if (plotWindowIsTemporarySourceSignalLassoSurface(window)) {
    if (const PlotWindowState* owner = plotWindowById(*app, window.sourceSignalDockOwnerWindowId);
        owner && !plotWindowIsSourceSignal(*owner)) {
      settingsWindow = owner;
    } else if (const PlotWindowState* target = plotWindowById(*app, app->viewerLassoTargetWindowId);
               target && !plotWindowIsSourceSignal(*target)) {
      settingsWindow = target;
    }
  }
  applySettingsStateToAppRuntime(app, settingsWindow->viewState, &settingsWindow->camera);
  for (auto& other : app->plotWindows) other.selected = other.windowId == window.windowId;
}

void ensureDefaultPlotWindow(AppState* app) {
  if (!app || !app->plotWindows.empty()) return;
  PlotWindowState window{};
  window.windowId = 1;
  window.rect = {0.0f, 0.0f, 1.0f, 1.0f};
  window.viewState = viewerStateWithModelCapabilities(app->viewerState);
  window.camera = app->cam;
  window.selected = true;
  app->plotWindows.push_back(window);
  app->focusedPlotWindowId = window.windowId;
  app->nextPlotWindowId = 2;
}

void focusPlotWindow(AppState* app, int id) {
  if (!app) return;
  captureFocusedPlotWindowFromApp(app);
  PlotWindowState* window = plotWindowById(app, id);
  if (!window) return;
  PlotWindowState copy = *window;
  applyPlotWindowToApp(app, copy);
}

void focusPlotWindowWithoutCapture(AppState* app, int id) {
  if (!app) return;
  PlotWindowState* window = plotWindowById(app, id);
  if (!window) return;
  PlotWindowState copy = *window;
  applyPlotWindowToApp(app, copy);
}

float plotWindowMinNormW(int windowWidth) {
  return std::min(0.88f, 180.0f / static_cast<float>(std::max(1, windowWidth)));
}

float plotWindowMinNormH(int windowHeight) {
  return std::min(0.88f, 140.0f / static_cast<float>(std::max(1, windowHeight)));
}

struct PlotWorkspaceGeometry {
  float topNorm = 0.0f;
  float heightNorm = 1.0f;
};

float plotWorkspaceTopNormForToolbar(bool showWorkspaceButtons, int windowHeight) {
  if (!showWorkspaceButtons) return 0.0f;
  return clampf(kViewerWorkspaceToolbarHeight / static_cast<float>(std::max(1, windowHeight)),
                0.0f,
                0.45f);
}

PlotWorkspaceGeometry plotWorkspaceGeometry(const AppState& app, int windowHeight) {
  PlotWorkspaceGeometry geometry{};
  geometry.topNorm = plotWorkspaceTopNormForToolbar(app.showWorkspaceButtons, windowHeight);
  geometry.heightNorm = std::max(0.05f, 1.0f - geometry.topNorm);
  return geometry;
}

float plotWorkspaceTopNorm(const AppState& app, int windowHeight) {
  return plotWorkspaceGeometry(app, windowHeight).topNorm;
}

struct PlotMenuRect {
  float x0 = 0.0f;
  float y0 = 0.0f;
  float x1 = 0.0f;
  float y1 = 0.0f;
};

bool pointInPlotMenuRect(const PlotMenuRect& rect, double x, double y);
PlotMenuRect plotMenuMainRect(const AppState& app, int width, int height);
float viewerMenuRowsX0(const PlotMenuRect& rect);
float viewerMenuRowsY0(const AppState& app, const PlotMenuRect& rect);

int clampViewerFontSize(int size) {
  return std::clamp(size, 0, 2);
}

const char* viewerFontSizeLabel(int size) {
  switch (clampViewerFontSize(size)) {
    case 1: return "Medium";
    case 2: return "Large";
    case 0:
    default: return "Small";
  }
}

float viewerFontScaleForSize(int size) {
  switch (clampViewerFontSize(size)) {
    case 1: return 1.12f;
    case 2: return 1.25f;
    case 0:
    default: return 1.0f;
  }
}

struct ViewerUiMetrics {
  float textScale = 1.0f;
  float rowHeight = 42.0f;
  float stackedRowHeight = 58.0f;
  float actionButtonRowHeight = 38.0f;
  float choiceRowHeight = 30.0f;
  float drawerTabHeight = 32.0f;
  float settingsSubtabHeight = 30.0f;
  float compactSelectorHeight = 24.0f;
  float titleTextScale = 1.0f;
  float titleExtraHeight = 0.0f;
  float drawerComfortMin = 390.0f;
  float drawerComfortMax = 540.0f;
};

ViewerUiMetrics viewerUiMetricsForFontSize(int size) {
  ViewerUiMetrics m{};
  const int clamped = clampViewerFontSize(size);
  m.textScale = viewerFontScaleForSize(clamped);
  m.rowHeight = clamped == 0 ? 42.0f : (clamped == 1 ? 47.0f : 52.0f);
  m.stackedRowHeight = clamped == 0 ? 58.0f : (clamped == 1 ? 64.0f : 71.0f);
  m.actionButtonRowHeight = clamped == 0 ? 38.0f : (clamped == 1 ? 42.0f : 45.0f);
  m.choiceRowHeight = clamped == 0 ? 30.0f : (clamped == 1 ? 34.0f : 38.0f);
  m.drawerTabHeight = clamped == 0 ? 32.0f : (clamped == 1 ? 36.0f : 40.0f);
  m.settingsSubtabHeight = clamped == 0 ? 30.0f : (clamped == 1 ? 34.0f : 38.0f);
  m.compactSelectorHeight = clamped == 0 ? 24.0f : (clamped == 1 ? 28.0f : 32.0f);
  m.titleTextScale = m.textScale;
  m.titleExtraHeight = clamped == 0 ? 0.0f : (clamped == 1 ? 3.0f : 6.0f);
  m.drawerComfortMin = clamped == 0 ? 390.0f : (clamped == 1 ? 430.0f : 470.0f);
  m.drawerComfortMax = clamped == 0 ? 540.0f : (clamped == 1 ? 590.0f : 640.0f);
  return m;
}

ViewerUiMetrics viewerUiMetrics(const AppState& app) {
  return viewerUiMetricsForFontSize(app.viewerFontSize);
}

float viewerChoiceTextBaselineOffset(const ViewerUiMetrics& metrics, bool rendererAvailable) {
  if (metrics.textScale <= 1.01f) return rendererAvailable ? 8.0f : 9.0f;
  return std::max(8.0f, metrics.choiceRowHeight * 0.5f - 6.0f * metrics.textScale);
}

float viewerRowTextBaselineOffset(const ViewerUiMetrics& metrics, bool rendererAvailable) {
  if (metrics.textScale <= 1.01f) return rendererAvailable ? 14.0f : 15.0f;
  return std::max(14.0f, metrics.rowHeight * 0.5f - 6.0f * metrics.textScale);
}

float viewerCompactTextBaselineOffset(const ViewerUiMetrics& metrics,
                                      float controlHeight,
                                      float textScale,
                                      bool rendererAvailable,
                                      float smallBaseline) {
  if (metrics.textScale <= 1.01f) return rendererAvailable ? smallBaseline : smallBaseline + 1.0f;
  return std::max(smallBaseline, controlHeight * 0.5f - 6.0f * textScale);
}

float viewerMenuDrawerWidthPixels(int width, int fontSize) {
  const float w = static_cast<float>(std::max(1, width));
  const ViewerUiMetrics metrics = viewerUiMetricsForFontSize(fontSize);
  // Workspace reservations should adapt to the available surface, but fine UI
  // metrics stay in GLFW logical pixels. Scaling row heights, text, padding, or
  // hit targets with fullscreen width would make the menu visually balloon.
  constexpr float kDrawerSmallWindowFraction = 0.44f;
  constexpr float kDrawerWideWindowFraction = 0.30f;
  constexpr float kDrawerFractionBlendStart = 900.0f;
  constexpr float kDrawerFractionBlendEnd = 1800.0f;
  const float reservedPlotWidth = std::min(320.0f, std::max(170.0f, w * 0.34f));
  const float maxWidth = std::max(168.0f, w - reservedPlotWidth);
  const float minWidth = std::min(metrics.drawerComfortMin, maxWidth);
  const float blend = clampf((w - kDrawerFractionBlendStart) /
                                 (kDrawerFractionBlendEnd - kDrawerFractionBlendStart),
                             0.0f,
                             1.0f);
  const float preferredFraction = kDrawerSmallWindowFraction +
                                  (kDrawerWideWindowFraction - kDrawerSmallWindowFraction) * blend;
  return clampf(w * preferredFraction, minWidth, std::min(maxWidth, metrics.drawerComfortMax));
}

constexpr double kViewerMenuSlideSeconds = 0.20;

float smoothAnimation01(double t) {
  const float x = clampf(static_cast<float>(t), 0.0f, 1.0f);
  return x * x * (3.0f - 2.0f * x);
}

float plotModelMenuSlideProgress(const AppState& app) {
  if (!app.plotModelMenuVisible) return 0.0f;
  if (app.plotModelMenuAnimStart < 0.0) {
    return app.plotModelMenuTargetVisible ? 1.0f : 0.0f;
  }
  const double age = glfwGetTime() - app.plotModelMenuAnimStart;
  const float eased = smoothAnimation01(age / kViewerMenuSlideSeconds);
  return app.plotModelMenuTargetVisible ? eased : (1.0f - eased);
}

float plotWorkspaceReservedLeftPixels(const AppState& app, int windowWidth) {
  return viewerMenuDrawerWidthPixels(windowWidth, app.viewerFontSize) * plotModelMenuSlideProgress(app);
}

PlotMenuRect plotWindowLogicalScreenRect(const AppState& app,
                                         const PlotWindowState& window,
                                         int windowWidth,
                                         int windowHeight) {
  const float w = static_cast<float>(std::max(1, windowWidth));
  const float h = static_cast<float>(std::max(1, windowHeight));
  const float left = plotWorkspaceReservedLeftPixels(app, windowWidth);
  const float availableW = std::max(1.0f, w - left);
  const float x0 = left + window.rect.x * availableW;
  const float y0 = window.rect.y * h;
  return {x0,
          y0,
          x0 + std::max(1.0f, window.rect.w * availableW),
          y0 + std::max(1.0f, window.rect.h * h)};
}

float plotWindowTitleBarLogicalHeight(const AppState& app, const PlotMenuRect& screenRect) {
  const float windowH = std::max(1.0f, screenRect.y1 - screenRect.y0);
  const ViewerUiMetrics metrics = viewerUiMetrics(app);
  const float target = 24.0f + metrics.titleExtraHeight;
  if (windowH < 88.0f) return clampf(windowH * 0.24f, 12.0f, std::min(20.0f + metrics.titleExtraHeight, windowH * 0.34f));
  return clampf(target, 20.0f, std::max(20.0f, windowH * 0.22f));
}

PlotMenuRect plotWindowContentLogicalScreenRect(const AppState& app,
                                                const PlotWindowState& window,
                                                int windowWidth,
                                                int windowHeight) {
  PlotMenuRect rect = plotWindowLogicalScreenRect(app, window, windowWidth, windowHeight);
  const float titleH = plotWindowTitleBarLogicalHeight(app, rect);
  rect.y0 = std::min(rect.y1 - 1.0f, rect.y0 + titleH);
  return rect;
}

PlotWindowRectNorm plotWorkspaceRect(const AppState& app,
                                     float x,
                                     float y,
                                     float w,
                                     float h,
                                     int windowHeight) {
  const PlotWorkspaceGeometry workspace = plotWorkspaceGeometry(app, windowHeight);
  return {x, workspace.topNorm + y * workspace.heightNorm, w, h * workspace.heightNorm};
}

PlotWindowRectNorm clampedPlotWindowRect(const AppState& app,
                                         PlotWindowRectNorm rect,
                                         int windowWidth,
                                         int windowHeight) {
  const float minW = plotWindowMinNormW(windowWidth);
  const PlotWorkspaceGeometry workspace = plotWorkspaceGeometry(app, windowHeight);
  const float workspaceTop = workspace.topNorm;
  const float maxH = workspace.heightNorm;
  const float minH = std::min(plotWindowMinNormH(windowHeight), maxH);
  rect.w = clampf(rect.w, minW, 1.0f);
  rect.h = clampf(rect.h, minH, maxH);
  rect.x = clampf(rect.x, 0.0f, std::max(0.0f, 1.0f - rect.w));
  rect.y = clampf(rect.y, workspaceTop, std::max(workspaceTop, 1.0f - rect.h));
  return rect;
}

PlotWindowRectNorm reflowPlotWindowRectForWorkspaceTop(PlotWindowRectNorm rect,
                                                       float oldTop,
                                                       float newTop) {
  const float oldHeight = std::max(0.05f, 1.0f - oldTop);
  const float newHeight = std::max(0.05f, 1.0f - newTop);
  const float workspaceY = (rect.y - oldTop) / oldHeight;
  const float workspaceH = rect.h / oldHeight;
  rect.y = newTop + workspaceY * newHeight;
  rect.h = workspaceH * newHeight;
  return rect;
}

void reflowPlotWindowsForWorkspaceResize(AppState* app, int windowWidth, int windowHeight) {
  if (!app || windowWidth <= 0 || windowHeight <= 0) return;
  if (app->workspaceLayoutWindowWidth <= 0 || app->workspaceLayoutWindowHeight <= 0) {
    app->workspaceLayoutWindowWidth = windowWidth;
    app->workspaceLayoutWindowHeight = windowHeight;
    app->workspaceLayoutTopNorm = plotWorkspaceTopNorm(*app, windowHeight);
    return;
  }
  const float newTop = plotWorkspaceTopNorm(*app, windowHeight);
  const float oldTop = app->workspaceLayoutTopNorm >= 0.0f
                           ? clampf(app->workspaceLayoutTopNorm, 0.0f, 0.45f)
                           : plotWorkspaceTopNorm(*app, app->workspaceLayoutWindowHeight);
  if (app->workspaceLayoutWindowWidth == windowWidth &&
      app->workspaceLayoutWindowHeight == windowHeight &&
      std::fabs(oldTop - newTop) <= 1e-6f) {
    return;
  }

  for (auto& window : app->plotWindows) {
    window.rect = reflowPlotWindowRectForWorkspaceTop(window.rect, oldTop, newTop);
    window.rect = clampedPlotWindowRect(*app, window.rect, windowWidth, windowHeight);
    if (window.sourceSignalDocked && plotWindowRectLooksRestorable(window.sourceSignalRestoreRect)) {
      window.sourceSignalRestoreRect =
          reflowPlotWindowRectForWorkspaceTop(window.sourceSignalRestoreRect, oldTop, newTop);
      window.sourceSignalRestoreRect =
          clampedPlotWindowRect(*app, window.sourceSignalRestoreRect, windowWidth, windowHeight);
    }
  }
  app->workspaceLayoutWindowWidth = windowWidth;
  app->workspaceLayoutWindowHeight = windowHeight;
  app->workspaceLayoutTopNorm = newTop;
}

bool viewerWindowGeometryUsableForWorkspace(int framebufferWidth,
                                            int framebufferHeight,
                                            int windowWidth,
                                            int windowHeight) {
  if (gWindowIconified.load() != 0) return false;
  if (framebufferWidth <= 1 || framebufferHeight <= 1) return false;
  // Iconify/restore can briefly report tiny logical sizes. Do not let those
  // transient values clamp or persist the normalized plot-window layout.
  return windowWidth >= 240 && windowHeight >= 180;
}

PlotWindowRectNorm defaultPlotWindowRectNearCursor(const AppState& app,
                                                   int windowWidth,
                                                   int windowHeight,
                                                   double cursorX,
                                                   double cursorY) {
  const bool first = app.plotWindows.empty();
  PlotWindowRectNorm rect{};
  rect.w = first ? 1.0f : 0.46f;
  rect.h = first ? plotWorkspaceGeometry(app, windowHeight).heightNorm : 0.46f;
  rect.x = first ? 0.0f : static_cast<float>(cursorX / std::max(1, windowWidth)) - rect.w * 0.5f;
  rect.y = first ? plotWorkspaceTopNorm(app, windowHeight)
                 : static_cast<float>(cursorY / std::max(1, windowHeight)) - rect.h * 0.5f;
  return clampedPlotWindowRect(app, rect, windowWidth, windowHeight);
}

bool pointInPlotWindowRect(const AppState& app,
                           const PlotWindowState& window,
                           int windowWidth,
                           int windowHeight,
                           double x,
                           double y) {
  if (plotWindowIsDockedSourceSignal(window)) return false;
  const PlotMenuRect rect = plotWindowLogicalScreenRect(app, window, windowWidth, windowHeight);
  return x >= rect.x0 && x <= rect.x1 && y >= rect.y0 && y <= rect.y1;
}

int plotWindowAt(const AppState& app, int windowWidth, int windowHeight, double x, double y) {
  for (auto it = app.plotWindows.rbegin(); it != app.plotWindows.rend(); ++it) {
    if (pointInPlotWindowRect(app, *it, windowWidth, windowHeight, x, y)) return it->windowId;
  }
  return -1;
}

float plotWindowAreaNorm(const PlotWindowState& window) {
  return std::max(0.0f, window.rect.w) * std::max(0.0f, window.rect.h);
}

void sortPlotWindowsForReadableStacking(AppState* app, int focusedId) {
  if (!app || app->plotWindows.size() < 2u) return;
  std::stable_sort(app->plotWindows.begin(),
                   app->plotWindows.end(),
                   [focusedId](const PlotWindowState& a, const PlotWindowState& b) {
                     const float areaA = plotWindowAreaNorm(a);
                     const float areaB = plotWindowAreaNorm(b);
                     if (std::abs(areaA - areaB) > 1e-5f) {
                       return areaA > areaB;
                     }
                     if (a.windowId == focusedId && b.windowId != focusedId) return false;
                     if (b.windowId == focusedId && a.windowId != focusedId) return true;
                     return false;
                   });
}

void bringPlotWindowToFront(AppState* app, int id) {
  if (!app || app->plotWindows.size() < 2u) return;
  auto it = std::find_if(app->plotWindows.begin(), app->plotWindows.end(),
                         [&](const PlotWindowState& window) { return window.windowId == id; });
  if (it == app->plotWindows.end()) return;
  PlotWindowState window = *it;
  app->plotWindows.erase(it);
  app->plotWindows.push_back(window);
  sortPlotWindowsForReadableStacking(app, id);
}

bool standardPlotLayoutNameReserved(const std::string& name);

void markLayoutPresetCustom(AppState* app) {
  if (!app) return;
  if (!standardPlotLayoutNameReserved(app->layoutPresetSelection)) {
    app->layoutPresetNameInput = app->layoutPresetSelection;
  }
  app->layoutPresetSelection = "Custom";
}

bool closePlotWindow(AppState* app, int id) {
  if (!app || app->plotWindows.size() <= 1u) return false;
  captureFocusedPlotWindowFromApp(app);
  auto it = std::find_if(app->plotWindows.begin(), app->plotWindows.end(),
                         [&](const PlotWindowState& window) { return window.windowId == id; });
  if (it == app->plotWindows.end()) return false;
  const bool closedFocused = id == app->focusedPlotWindowId;
  releasePlotWindowGpuCaches(&(*it));
  app->plotWindows.erase(it);
  if (closedFocused && !app->plotWindows.empty()) {
    focusPlotWindow(app, app->plotWindows.back().windowId);
  }
  markLayoutPresetCustom(app);
  logViewerEvent(std::string("Closed plot window: id=") + std::to_string(id));
  return true;
}

bool plotModelIsAnalyticalScope(int plotModel);

void fitAnalyticalScopeCamera(PlotWindowState* window) {
  if (!window || !plotModelIsAnalyticalScope(window->viewState.plotModel)) return;
  float minX = kScopePlotLeft;
  float maxX = kScopePlotRight;
  float minY = kScopePlotBottom;
  float maxY = kScopePlotTop;
  const auto includeVertices = [&](const std::vector<float>& vertices) {
    for (size_t i = 0; i + 2u < vertices.size(); i += 3u) {
      const float x = vertices[i + 0u];
      const float y = vertices[i + 1u];
      if (!std::isfinite(x) || !std::isfinite(y)) continue;
      minX = std::min(minX, x);
      maxX = std::max(maxX, x);
      minY = std::min(minY, y);
      maxY = std::max(maxY, y);
    }
  };
  const auto includeBounds = [&](const Vec3& lo, const Vec3& hi) {
    if (!std::isfinite(lo.x) || !std::isfinite(lo.y) ||
        !std::isfinite(hi.x) || !std::isfinite(hi.y)) {
      return;
    }
    minX = std::min(minX, std::min(lo.x, hi.x));
    maxX = std::max(maxX, std::max(lo.x, hi.x));
    minY = std::min(minY, std::min(lo.y, hi.y));
    maxY = std::max(maxY, std::max(lo.y, hi.y));
  };
  if (window->derivedMeshValid) {
    if (window->derivedMesh.hasFitBounds) {
      includeBounds(window->derivedMesh.fitMin, window->derivedMesh.fitMax);
    }
    includeVertices(window->derivedMesh.pointVerts);
    includeVertices(window->derivedMesh.lineVerts);
    includeVertices(window->derivedMesh.scopeFillVerts);
  }
  const bool histogram =
      window->viewState.plotModel == ChromaspaceViewer::kPlotModelHistogram;
  if (histogram) {
    minX -= 0.04f;
    maxX += 0.16f;
    minY -= 0.15f;
    maxY += 0.04f;
  } else {
    minX -= 0.18f;
    maxX += 0.04f;
    minY -= 0.04f;
    maxY += 0.04f;
  }
  const float centerX = 0.5f * (minX + maxX);
  const float centerY = 0.5f * (minY + maxY);
  const float halfExtent =
      std::max(0.25f,
               std::max(0.5f * (maxX - minX),
                        0.5f * (maxY - minY))) *
      1.035f;
  window->camera.orthographic = true;
  window->camera.orthographicView = -1;
  window->camera.distance = clampf(halfExtent * 6.0f, 1.0f, kMaxCameraDistance);
  window->camera.panX = -centerX;
  window->camera.panY = -centerY;
  window->camera.qx = 0.0f;
  window->camera.qy = 0.0f;
  window->camera.qz = 0.0f;
  window->camera.qw = 1.0f;
}

bool fitPlotWindowCameraToCurrentContent(AppState* app,
                                         PlotWindowState* window,
                                         int windowWidth,
                                         int windowHeight,
                                         int fbWidth,
                                         int fbHeight);
void addPlotWindow(AppState* app, int plotModel, int windowWidth, int windowHeight, double cursorX, double cursorY) {
  if (!app) return;
  ensureDefaultPlotWindow(app);
  captureFocusedPlotWindowFromApp(app);
  PlotWindowState window{};
  window.windowId = app->nextPlotWindowId++;
  window.rect = defaultPlotWindowRectNearCursor(*app, windowWidth, windowHeight, cursorX, cursorY);
  window.viewState = viewerStateWithModelCapabilities(app->viewerState);
  window.viewState.plotModel =
      std::clamp(plotModel, 0, ChromaspaceViewer::kPlotModelCount - 1);
  window.viewState = viewerStateForPlotModel(window.viewState, window.viewState.plotModel);
  window.viewState.stateRevision = std::max<uint64_t>(window.viewState.stateRevision + 1, 1);
  if (plotModelIsAnalyticalScope(window.viewState.plotModel)) {
    resetAnalyticalScopeCamera(
        &window.camera,
        window.viewState.plotModel == ChromaspaceViewer::kPlotModelHistogram);
  } else {
    resetCamera(&window.camera);
  }
  app->plotWindows.push_back(window);
  focusPlotWindow(app, window.windowId);
  sortPlotWindowsForReadableStacking(app, window.windowId);
  logViewerEvent(std::string("Added plot window: id=") + std::to_string(window.windowId) +
                 " model=" + ChromaspaceViewer::plotModelLabel(window.viewState.plotModel));
}

bool plotWindowIsDockedSourceSignal(const PlotWindowState& window) {
  return plotWindowIsSourceSignal(window) && window.sourceSignalDocked;
}

bool plotWindowCanOwnViewerLassoSelection(const PlotWindowState& window) {
  const auto state = viewerStateWithModelCapabilities(window.viewState);
  return !plotWindowIsSourceSignal(window) &&
         ChromaspaceViewer::volumeSlicingSupported(state, false);
}

constexpr int kSlicingVectorCount = 6;

bool viewerSourceSelectionsSynced(const AppState& app) {
  return app.viewerState.sourceSyncSelections;
}

bool viewerCommonPlotSettingsSynced(const AppState& app) {
  return app.viewerState.sourceSyncCommonPlotSettings;
}

bool copyCommonPlotSettings(ChromaspaceViewer::ViewerRuntimeState* target,
                            const ChromaspaceViewer::ViewerRuntimeState& source) {
  if (!target) return false;
  bool changed = false;
  auto copyBool = [&](bool* field, bool value) {
    if (*field == value) return;
    *field = value;
    changed = true;
  };
  auto copyInt = [&](int* field, int value) {
    if (*field == value) return;
    *field = value;
    changed = true;
  };
  copyBool(&target->sourceSyncCommonPlotSettings, source.sourceSyncCommonPlotSettings);
  copyBool(&target->plotDisplayLinear, source.plotDisplayLinear);
  copyInt(&target->plotDisplayLinearTransfer, source.plotDisplayLinearTransfer);
  copyBool(&target->showOverflow, source.showOverflow);
  copyBool(&target->highlightOverflow, source.highlightOverflow);
  return changed;
}

void propagateCommonPlotSettingsToPlotWindows(AppState* app) {
  if (!app) return;
  const auto source = viewerStateWithModelCapabilities(app->viewerState);
  for (auto& window : app->plotWindows) {
    auto state = viewerStateWithModelCapabilities(window.viewState);
    if (!copyCommonPlotSettings(&state, source)) continue;
    state.stateRevision = std::max<uint64_t>(state.stateRevision + 1, 1);
    window.viewState = viewerStateWithModelCapabilities(state);
  }
}

bool viewerImageLassoSessionActive(const AppState& app) {
  if (app.viewerState.volumeSliceLassoRegion || app.viewerLassoDrawing) return true;
  for (const auto& window : app.plotWindows) {
    if (viewerStateWithModelCapabilities(window.viewState).volumeSliceLassoRegion) {
      return true;
    }
  }
  return false;
}

PlotWindowState* sourceSignalPlotWindow(AppState* app) {
  if (!app) return nullptr;
  for (auto& window : app->plotWindows) {
    if (plotWindowIsSourceSignal(window)) return &window;
  }
  return nullptr;
}

const PlotWindowState* sourceSignalPlotWindow(const AppState& app) {
  for (const auto& window : app.plotWindows) {
    if (plotWindowIsSourceSignal(window)) return &window;
  }
  return nullptr;
}

PlotWindowState* sourceSignalPlotWindowAt(AppState* app,
                                          int windowWidth,
                                          int windowHeight,
                                          double x,
                                          double y) {
  if (!app) return nullptr;
  for (auto it = app->plotWindows.rbegin(); it != app->plotWindows.rend(); ++it) {
    if (plotWindowIsSourceSignal(*it) &&
        pointInPlotWindowRect(*app, *it, windowWidth, windowHeight, x, y)) {
      return &(*it);
    }
  }
  return nullptr;
}

PlotWindowState* sourceSignalDockOwnerWindow(AppState* app, const PlotWindowState* sourceWindow = nullptr) {
  if (!app) return nullptr;
  const int preferredId =
      sourceWindow && sourceWindow->sourceSignalDockOwnerWindowId >= 0
          ? sourceWindow->sourceSignalDockOwnerWindowId
          : app->viewerLassoTargetWindowId;
  if (PlotWindowState* owner = plotWindowById(app, preferredId);
      owner && plotWindowCanOwnViewerLassoSelection(*owner)) {
    return owner;
  }
  if (PlotWindowState* focused = focusedPlotWindow(app);
      focused && plotWindowCanOwnViewerLassoSelection(*focused)) {
    return focused;
  }
  for (auto it = app->plotWindows.rbegin(); it != app->plotWindows.rend(); ++it) {
    if (plotWindowCanOwnViewerLassoSelection(*it)) return &(*it);
  }
  return nullptr;
}

const PlotWindowState* sourceSignalDockOwnerWindow(const AppState& app,
                                                   const PlotWindowState& sourceWindow) {
  if (const PlotWindowState* owner = plotWindowById(app, sourceWindow.sourceSignalDockOwnerWindowId);
      owner && plotWindowCanOwnViewerLassoSelection(*owner)) {
    return owner;
  }
  if (const PlotWindowState* owner = plotWindowById(app, app.viewerLassoTargetWindowId);
      owner && plotWindowCanOwnViewerLassoSelection(*owner)) {
    return owner;
  }
  if (const PlotWindowState* focused = focusedPlotWindow(app);
      focused && plotWindowCanOwnViewerLassoSelection(*focused)) {
    return focused;
  }
  for (auto it = app.plotWindows.rbegin(); it != app.plotWindows.rend(); ++it) {
    if (plotWindowCanOwnViewerLassoSelection(*it)) return &(*it);
  }
  return nullptr;
}

bool plotWindowSupportsSlicingQuickButton(const PlotWindowState& window) {
  return !plotWindowIsSourceSignal(window) &&
         window.viewState.plotModel != ChromaspaceViewer::kPlotModelGlossView;
}

bool plotWindowShowsSlicingQuickButton(const AppState& app, const PlotWindowState& window) {
  return app.showSliceButtonInPlotWindows && plotWindowSupportsSlicingQuickButton(window);
}

PlotMenuRect slicingQuickButtonRect(const AppState& app,
                                    const PlotWindowState& window,
                                    int windowWidth,
                                    int windowHeight) {
  if (!plotWindowShowsSlicingQuickButton(app, window)) return {};
  const PlotMenuRect content = plotWindowContentLogicalScreenRect(app, window, windowWidth, windowHeight);
  const float size = 34.0f;
  const float margin = 10.0f;
  const float x0 = clampf(content.x0 + margin,
                          content.x0 + 4.0f,
                          std::max(content.x0 + 4.0f, content.x1 - size - 4.0f));
  const float y0 = clampf(content.y1 - size - margin,
                          content.y0 + 4.0f,
                          std::max(content.y0 + 4.0f, content.y1 - size - 4.0f));
  return {x0, y0, x0 + size, y0 + size};
}

float bottomLeftControlLaneOffset(const AppState& app,
                                  const PlotWindowState& owner,
                                  int windowWidth,
                                  int windowHeight) {
  if (!plotWindowShowsSlicingQuickButton(app, owner)) return 0.0f;
  const PlotMenuRect button = slicingQuickButtonRect(app, owner, windowWidth, windowHeight);
  return std::max(0.0f, button.x1 - button.x0 + 8.0f);
}

struct SlicingQuickDrawerRects {
  PlotMenuRect drawer{};
  std::array<PlotMenuRect, kSlicingVectorCount> vectors{};
  PlotMenuRect lasso{};
};

PlotMenuRect slicingQuickDrawerRect(const AppState& app,
                                    const PlotWindowState& window,
                                    int windowWidth,
                                    int windowHeight) {
  const PlotMenuRect content = plotWindowContentLogicalScreenRect(app, window, windowWidth, windowHeight);
  const PlotMenuRect button = slicingQuickButtonRect(app, window, windowWidth, windowHeight);
  if (button.x1 <= button.x0 || button.y1 <= button.y0) return {};
  const float pad = 9.0f;
  const float gap = 7.0f;
  const float maxWidth = std::max(80.0f, content.x1 - button.x0 - 6.0f);
  const float preferredItem = 24.0f;
  const float item =
      clampf((maxWidth - pad * 2.0f - gap * 6.0f) / 7.0f, 14.0f, preferredItem);
  const float width = std::min(maxWidth, pad * 2.0f + item * 7.0f + gap * 6.0f);
  const float height = pad * 2.0f + item;
  const float x0 = button.x0;
  float y1 = button.y0 - 7.0f;
  float y0 = y1 - height;
  if (y0 < content.y0 + 4.0f) {
    y0 = std::min(content.y1 - height - 4.0f, button.y1 + 7.0f);
    y1 = y0 + height;
  }
  return {x0, y0, std::min(content.x1 - 4.0f, x0 + width), y1};
}

SlicingQuickDrawerRects slicingQuickDrawerItemRects(const AppState& app,
                                                    const PlotWindowState& window,
                                                    int windowWidth,
                                                    int windowHeight) {
  SlicingQuickDrawerRects out{};
  out.drawer = slicingQuickDrawerRect(app, window, windowWidth, windowHeight);
  if (out.drawer.x1 <= out.drawer.x0 || out.drawer.y1 <= out.drawer.y0) return out;
  const float pad = 9.0f;
  const float gap = 7.0f;
  const float available = std::max(20.0f, out.drawer.x1 - out.drawer.x0 - pad * 2.0f);
  const float item = clampf((available - gap * 6.0f) / 7.0f, 12.0f, 24.0f);
  const float y0 = out.drawer.y0 + (out.drawer.y1 - out.drawer.y0 - item) * 0.5f;
  float x = out.drawer.x0 + pad;
  for (int i = 0; i < kSlicingVectorCount; ++i) {
    out.vectors[static_cast<size_t>(i)] = {x, y0, x + item, y0 + item};
    x += item + gap;
  }
  out.lasso = {x, y0, x + item, y0 + item};
  return out;
}

int slicingQuickDrawerVectorIndexAt(const SlicingQuickDrawerRects& rects, double x, double y) {
  for (int i = 0; i < kSlicingVectorCount; ++i) {
    const PlotMenuRect& rect = rects.vectors[static_cast<std::size_t>(i)];
    if (x >= rect.x0 && x <= rect.x1 && y >= rect.y0 && y <= rect.y1) return i;
  }
  return -1;
}

bool pointInSlicingQuickDrawerLasso(const SlicingQuickDrawerRects& rects, double x, double y) {
  return x >= rects.lasso.x0 && x <= rects.lasso.x1 && y >= rects.lasso.y0 && y <= rects.lasso.y1;
}

PlotMenuRect sourceSignalDockButtonRect(const AppState& app,
                                        const PlotWindowState& sourceWindow,
                                        int windowWidth,
                                        int windowHeight) {
  const PlotWindowState* owner = sourceSignalDockOwnerWindow(app, sourceWindow);
  if (!owner) return {};
  const PlotMenuRect content = plotWindowContentLogicalScreenRect(app, *owner, windowWidth, windowHeight);
  const float buttonW = 48.0f;
  const float buttonH = 34.0f;
  const float margin = 10.0f;
  const float laneOffset = bottomLeftControlLaneOffset(app, *owner, windowWidth, windowHeight);
  const float x0 = clampf(content.x0 + margin + laneOffset,
                          content.x0 + 4.0f,
                          std::max(content.x0 + 4.0f, content.x1 - buttonW - 4.0f));
  const float y0 = clampf(content.y1 - buttonH - margin,
                          content.y0 + 4.0f,
                          std::max(content.y0 + 4.0f, content.y1 - buttonH - 4.0f));
  return {x0, y0, x0 + buttonW, y0 + buttonH};
}

PlotWindowState* dockedSourceSignalWindowAtPoint(AppState* app,
                                                 int windowWidth,
                                                 int windowHeight,
                                                 double x,
                                                 double y) {
  if (!app) return nullptr;
  for (auto it = app->plotWindows.rbegin(); it != app->plotWindows.rend(); ++it) {
    if (!plotWindowIsDockedSourceSignal(*it)) continue;
    if (pointInPlotMenuRect(sourceSignalDockButtonRect(*app, *it, windowWidth, windowHeight), x, y)) {
      return &(*it);
    }
  }
  return nullptr;
}

bool plotWindowRectLooksRestorable(const PlotWindowRectNorm& rect) {
  return rect.w > 0.08f && rect.h > 0.08f && rect.x >= -0.001f && rect.y >= -0.001f;
}

void dockSourceSignalForLasso(AppState* app,
                              PlotWindowState* sourceWindow,
                              int windowWidth,
                              int windowHeight) {
  if (!app || !sourceWindow || !plotWindowIsSourceSignal(*sourceWindow) ||
      !viewerImageLassoSessionActive(*app)) {
    return;
  }
  PlotWindowState* owner = sourceSignalDockOwnerWindow(app, sourceWindow);
  if (!owner) return;
  if (!sourceWindow->sourceSignalDocked) {
    sourceWindow->sourceSignalRestoreRect = sourceWindow->rect;
  }
  sourceWindow->sourceSignalDockOwnerWindowId = owner->windowId;
  sourceWindow->sourceSignalDocked = true;
  sourceWindow->sourceSignalDockAnimStart = glfwGetTime();
  sourceWindow->sourceSignalDockAnimatingToDock = true;
  if (app->focusedPlotWindowId == sourceWindow->windowId) {
    focusPlotWindow(app, owner->windowId);
  }
  logViewerEvent(std::string("Docked Source Signal lasso surface to plot window: owner=") +
                 std::to_string(owner->windowId));
  (void)windowWidth;
  (void)windowHeight;
}

void restoreDockedSourceSignalWindow(AppState* app,
                                     PlotWindowState* sourceWindow,
                                     int windowWidth,
                                     int windowHeight) {
  if (!app || !sourceWindow || !plotWindowIsDockedSourceSignal(*sourceWindow)) return;
  PlotWindowState* owner = sourceSignalDockOwnerWindow(app, sourceWindow);
  if (plotWindowRectLooksRestorable(sourceWindow->sourceSignalRestoreRect)) {
    sourceWindow->rect =
        clampedPlotWindowRect(*app, sourceWindow->sourceSignalRestoreRect, windowWidth, windowHeight);
  } else if (owner) {
    const PlotMenuRect ownerContent = plotWindowContentLogicalScreenRect(*app, *owner, windowWidth, windowHeight);
    const float left = plotWorkspaceReservedLeftPixels(*app, windowWidth);
    const float availableW = std::max(1.0f, static_cast<float>(windowWidth) - left);
    PlotWindowRectNorm rect{};
    rect.w = 0.38f;
    rect.h = std::min(0.42f, std::max(0.28f, owner->rect.h * 0.62f));
    const float logicalX = ownerContent.x0 + 18.0f;
    const float logicalY = std::max(ownerContent.y0 + 18.0f, ownerContent.y1 - rect.h * windowHeight - 18.0f);
    rect.x = (logicalX - left) / availableW;
    rect.y = logicalY / static_cast<float>(std::max(1, windowHeight));
    sourceWindow->rect = clampedPlotWindowRect(*app, rect, windowWidth, windowHeight);
  } else {
    sourceWindow->rect = clampedPlotWindowRect(*app,
                                               {0.08f, plotWorkspaceTopNorm(*app, windowHeight) + 0.06f, 0.42f, 0.42f},
                                               windowWidth,
                                               windowHeight);
  }
  const int previousLassoTarget = app->viewerLassoTargetWindowId;
  sourceWindow->sourceSignalDocked = false;
  sourceWindow->sourceSignalDockAnimStart = glfwGetTime();
  sourceWindow->sourceSignalDockAnimatingToDock = false;
  focusPlotWindow(app, sourceWindow->windowId);
  app->viewerLassoTargetWindowId = previousLassoTarget;
  bringPlotWindowToFront(app, sourceWindow->windowId);
  logViewerEvent("Restored docked Source Signal lasso surface.");
}

PlotWindowState* activeViewerLassoTargetWindow(AppState* app) {
  if (!app || viewerSourceSelectionsSynced(*app)) return nullptr;
  if (PlotWindowState* target = plotWindowById(app, app->viewerLassoTargetWindowId);
      target && plotWindowCanOwnViewerLassoSelection(*target)) {
    return target;
  }
  if (PlotWindowState* focused = focusedPlotWindow(app);
      focused && plotWindowCanOwnViewerLassoSelection(*focused)) {
    app->viewerLassoTargetWindowId = focused->windowId;
    return focused;
  }
  for (auto it = app->plotWindows.rbegin(); it != app->plotWindows.rend(); ++it) {
    if (plotWindowCanOwnViewerLassoSelection(*it)) {
      app->viewerLassoTargetWindowId = it->windowId;
      return &(*it);
    }
  }
  app->viewerLassoTargetWindowId = -1;
  return nullptr;
}

const PlotWindowState* activeViewerLassoTargetWindow(const AppState& app) {
  if (viewerSourceSelectionsSynced(app)) return nullptr;
  if (const PlotWindowState* target = plotWindowById(app, app.viewerLassoTargetWindowId);
      target && plotWindowCanOwnViewerLassoSelection(*target)) {
    return target;
  }
  if (const PlotWindowState* focused = focusedPlotWindow(app);
      focused && plotWindowCanOwnViewerLassoSelection(*focused)) {
    return focused;
  }
  for (auto it = app.plotWindows.rbegin(); it != app.plotWindows.rend(); ++it) {
    if (plotWindowCanOwnViewerLassoSelection(*it)) return &(*it);
  }
  return nullptr;
}

void rememberViewerLassoTargetFromCurrentFocus(AppState* app) {
  if (!app) return;
  if (PlotWindowState* focused = focusedPlotWindow(app);
      focused && plotWindowCanOwnViewerLassoSelection(*focused)) {
    app->viewerLassoTargetWindowId = focused->windowId;
  }
}

void rememberViewerLassoTargetFromSettingsWindow(AppState* app) {
  if (!app) return;
  if (PlotWindowState* settings = effectiveSettingsPlotWindow(app);
      settings && plotWindowCanOwnViewerLassoSelection(*settings)) {
    app->viewerLassoTargetWindowId = settings->windowId;
    return;
  }
  rememberViewerLassoTargetFromCurrentFocus(app);
}

const PlotWindowState* activeSourceSignalLassoWindow(const AppState& app) {
  if (const PlotWindowState* focused = focusedPlotWindow(app);
      focused && plotWindowIsSourceSignal(*focused) && !plotWindowIsDockedSourceSignal(*focused)) {
    return focused;
  }
  const PlotWindowState* source = sourceSignalPlotWindow(app);
  return source && !plotWindowIsDockedSourceSignal(*source) ? source : nullptr;
}

PlotWindowRectNorm sourceSignalLassoSurfaceRectForOwner(const AppState& app,
                                                        const PlotWindowState* owner,
                                                        int windowWidth,
                                                        int windowHeight) {
  const float left = plotWorkspaceReservedLeftPixels(app, windowWidth);
  const float availableW = std::max(1.0f, static_cast<float>(windowWidth) - left);
  const float toolbarBottom = plotWorkspaceTopNorm(app, windowHeight) * static_cast<float>(windowHeight);
  if (!owner) {
    return clampedPlotWindowRect(app,
                                 {0.08f,
                                  plotWorkspaceTopNorm(app, windowHeight) + 0.06f,
                                  0.46f,
                                  0.46f},
                                 windowWidth,
                                 windowHeight);
  }

  const PlotMenuRect ownerContent =
      plotWindowContentLogicalScreenRect(app, *owner, windowWidth, windowHeight);
  const float ownerW = std::max(1.0f, ownerContent.x1 - ownerContent.x0);
  const float ownerH = std::max(1.0f, ownerContent.y1 - ownerContent.y0);
  const float targetW = clampf(ownerW * 0.72f,
                               std::min(300.0f, availableW * 0.72f),
                               std::min(620.0f, availableW - 20.0f));
  const float targetH = clampf(ownerH * 0.68f,
                               std::min(220.0f, static_cast<float>(windowHeight) * 0.55f),
                               std::min(520.0f, static_cast<float>(windowHeight) - toolbarBottom - 20.0f));
  const float xPx = clampf(ownerContent.x0 + (ownerW - targetW) * 0.5f,
                           left + 10.0f,
                           std::max(left + 10.0f, static_cast<float>(windowWidth) - targetW - 10.0f));
  const float yPx = clampf(ownerContent.y0 + (ownerH - targetH) * 0.5f,
                           toolbarBottom + 10.0f,
                           std::max(toolbarBottom + 10.0f,
                                    static_cast<float>(windowHeight) - targetH - 10.0f));
  return clampedPlotWindowRect(app,
                               {(xPx - left) / availableW,
                                yPx / static_cast<float>(std::max(1, windowHeight)),
                                targetW / availableW,
                                targetH / static_cast<float>(std::max(1, windowHeight))},
                               windowWidth,
                               windowHeight);
}

void ensureSourceSignalWindowForLasso(AppState* app,
                                      int windowWidth,
                                      int windowHeight,
                                      bool focusExisting) {
  if (!app || !viewerImageLassoSessionActive(*app)) return;
  if (focusExisting) rememberViewerLassoTargetFromSettingsWindow(app);
  if (PlotWindowState* existing = sourceSignalPlotWindow(app)) {
    PlotWindowState* owner = sourceSignalDockOwnerWindow(app, existing);
    const int ownerId = owner ? owner->windowId : -1;
    if (owner) {
      existing->sourceSignalDockOwnerWindowId = owner->windowId;
    }
    if (focusExisting && plotWindowIsDockedSourceSignal(*existing)) {
      restoreDockedSourceSignalWindow(app, existing, windowWidth, windowHeight);
      if (PlotWindowState* restoredOwner = plotWindowById(app, ownerId)) {
        app->focusedPlotWindowId = restoredOwner->windowId;
        for (auto& window : app->plotWindows) {
          window.selected = window.windowId == restoredOwner->windowId;
        }
        applySettingsStateToAppRuntime(app, restoredOwner->viewState, &restoredOwner->camera);
      }
      return;
    }
    if (focusExisting) {
      bringPlotWindowToFront(app, existing->windowId);
      if (PlotWindowState* restoredOwner = plotWindowById(app, ownerId)) {
        app->focusedPlotWindowId = restoredOwner->windowId;
        for (auto& window : app->plotWindows) {
          window.selected = window.windowId == restoredOwner->windowId;
        }
        applySettingsStateToAppRuntime(app, restoredOwner->viewState, &restoredOwner->camera);
      } else {
        focusPlotWindow(app, existing->windowId);
      }
    }
    return;
  }
  PlotWindowState* ownerBeforeCreate = sourceSignalDockOwnerWindow(app);
  const int ownerId = ownerBeforeCreate ? ownerBeforeCreate->windowId : -1;
  ChromaspaceViewer::ViewerRuntimeState ownerViewState{};
  CameraState ownerCamera{};
  const bool hasOwnerSnapshot = ownerBeforeCreate != nullptr;
  if (hasOwnerSnapshot) {
    ownerViewState = ownerBeforeCreate->viewState;
    ownerCamera = ownerBeforeCreate->camera;
  }
  const double cursorX = (app->hoverX > 0.0) ? app->hoverX : static_cast<double>(windowWidth) * 0.5;
  const double cursorY = (app->hoverY > 0.0) ? app->hoverY : static_cast<double>(windowHeight) * 0.5;
  addPlotWindow(app,
                ChromaspaceViewer::kPlotModelSourceSignal,
                windowWidth,
                windowHeight,
                cursorX,
                cursorY);
  if (PlotWindowState* source = sourceSignalPlotWindow(app)) {
    source->sourceSignalDockOwnerWindowId = ownerId;
    if (hasOwnerSnapshot) {
      source->rect =
          sourceSignalLassoSurfaceRectForOwner(*app, plotWindowById(app, ownerId), windowWidth, windowHeight);
    }
    source->sourceSignalRestoreRect = source->rect;
    source->sourceSignalTemporaryLassoSurface = true;
    bringPlotWindowToFront(app, source->windowId);
  }
  if (hasOwnerSnapshot) {
    if (PlotWindowState* ownerAfterCreate = plotWindowById(app, ownerId)) {
      ownerAfterCreate->viewState = ownerViewState;
      ownerAfterCreate->camera = ownerCamera;
      for (auto& window : app->plotWindows) window.selected = window.windowId == ownerId;
    }
    app->focusedPlotWindowId = ownerId;
    app->viewerLassoTargetWindowId = ownerId;
    applySettingsStateToAppRuntime(app, ownerViewState, &ownerCamera);
  }
  logViewerEvent("Opened Source Signal window for viewer lasso drawing.");
}

void propagateViewerLassoEnabledToPlotWindows(AppState* app) {
  if (!app) return;
  const bool enabled = app->viewerState.volumeSliceLassoRegion;
  PlotWindowState* target = nullptr;
  if (enabled && !viewerSourceSelectionsSynced(*app)) {
    target = activeViewerLassoTargetWindow(app);
  }
  for (auto& window : app->plotWindows) {
    auto state = viewerStateWithModelCapabilities(window.viewState);
    const bool nextEnabled =
        enabled &&
        ChromaspaceViewer::volumeSlicingSupported(state, false) &&
        (viewerSourceSelectionsSynced(*app) ||
         (target && target->windowId == window.windowId));
    if (state.volumeSliceLassoRegion == nextEnabled) continue;
    state.volumeSliceLassoRegion = nextEnabled;
    state.stateRevision = std::max<uint64_t>(state.stateRevision + 1, 1);
    window.viewState = viewerStateWithModelCapabilities(state);
  }
}

void propagateSourceSelectionSyncToPlotWindows(AppState* app) {
  if (!app) return;
  const bool synced = app->viewerState.sourceSyncSelections;
  PlotWindowState* unsyncedInitialTarget = nullptr;
  if (!synced) {
    unsyncedInitialTarget = activeViewerLassoTargetWindow(app);
  } else {
    PlotWindowState* syncSource = plotWindowById(app, app->viewerLassoTargetWindowId);
    if (!syncSource || !plotWindowCanOwnViewerLassoSelection(*syncSource)) {
      syncSource = focusedPlotWindow(app);
    }
    if (syncSource && plotWindowCanOwnViewerLassoSelection(*syncSource) &&
        !syncSource->viewerLassoData.empty()) {
      app->viewerLassoStrokes = syncSource->viewerLassoStrokes;
      app->viewerLassoRevision = std::max<uint64_t>(syncSource->viewerLassoRevision, 1);
      app->viewerLassoData = syncSource->viewerLassoData;
    }
  }
  for (auto& window : app->plotWindows) {
    window.viewState.sourceSyncSelections = synced;
    window.viewState.stateRevision = std::max<uint64_t>(window.viewState.stateRevision + 1, 1);
    if (!synced && (&window == unsyncedInitialTarget) &&
        window.viewerLassoData.empty() && !app->viewerLassoData.empty() &&
        plotWindowCanOwnViewerLassoSelection(window)) {
      window.viewerLassoStrokes = app->viewerLassoStrokes;
      window.viewerLassoRevision = app->viewerLassoRevision;
      window.viewerLassoData = app->viewerLassoData;
    }
  }
}

bool sourceSignalImageRectForCanvas(const AppState& app,
                                    const PlotWindowState& window,
                                    int canvasWidth,
                                    int canvasHeight,
                                    bool topLeftY,
                                    float* outX0,
                                    float* outY0,
                                    float* outX1,
                                    float* outY1) {
  if (!outX0 || !outY0 || !outX1 || !outY1 || canvasWidth <= 0 || canvasHeight <= 0) {
    return false;
  }
  const PlotMenuRect screenRect = plotWindowContentLogicalScreenRect(app, window, canvasWidth, canvasHeight);
  const float plotX = screenRect.x0;
  const float plotTop = screenRect.y0;
  const float plotW = std::max(1.0f, screenRect.x1 - screenRect.x0);
  const float plotH = std::max(1.0f, screenRect.y1 - screenRect.y0);
  const int proxyW = app.sourceSignalProxyWidth > 0 ? app.sourceSignalProxyWidth : app.sourceSignalSourceWidth;
  const int proxyH = app.sourceSignalProxyHeight > 0 ? app.sourceSignalProxyHeight : app.sourceSignalSourceHeight;
  if (proxyW <= 0 || proxyH <= 0) {
    if (topLeftY) {
      *outX0 = plotX;
      *outY0 = plotTop;
      *outX1 = plotX + plotW;
      *outY1 = plotTop + plotH;
    } else {
      *outX0 = plotX;
      *outY0 = static_cast<float>(canvasHeight) - plotTop - plotH;
      *outX1 = plotX + plotW;
      *outY1 = *outY0 + plotH;
    }
    return true;
  }

  const float pad = std::max(10.0f, std::min(plotW, plotH) * 0.025f);
  const float availableW = std::max(1.0f, plotW - pad * 2.0f);
  const float availableH = std::max(1.0f, plotH - pad * 2.0f - 26.0f);
  const float sourceAspect =
      static_cast<float>(std::max(1, proxyW)) / static_cast<float>(std::max(1, proxyH));
  float drawW = availableW;
  float drawH = drawW / sourceAspect;
  if (drawH > availableH) {
    drawH = availableH;
    drawW = drawH * sourceAspect;
  }

  const float localX0 = (plotW - drawW) * 0.5f;
  const float localY0Bottom = (plotH - drawH) * 0.5f - 4.0f;
  *outX0 = plotX + localX0;
  *outX1 = *outX0 + drawW;
  if (topLeftY) {
    *outY0 = plotTop + plotH - (localY0Bottom + drawH);
    *outY1 = plotTop + plotH - localY0Bottom;
  } else {
    const float plotBottom = static_cast<float>(canvasHeight) - plotTop - plotH;
    *outY0 = plotBottom + localY0Bottom;
    *outY1 = *outY0 + drawH;
  }
  return *outX1 > *outX0 && *outY1 > *outY0;
}

void ensurePlotWindowCount(AppState* app, int count, int windowWidth, int windowHeight) {
  if (!app) return;
  ensureDefaultPlotWindow(app);
  while (static_cast<int>(app->plotWindows.size()) < count) {
    const int index = static_cast<int>(app->plotWindows.size());
    const int model = index % ChromaspaceViewer::kPlotModelCount;
    addPlotWindow(app,
                  model,
                  windowWidth,
                  windowHeight,
                  static_cast<double>(windowWidth) * (0.35 + 0.08 * static_cast<double>(index % 4)),
                  static_cast<double>(windowHeight) * (0.35 + 0.08 * static_cast<double>(index % 3)));
  }
}

bool viewerNamesEqualNoCase(const std::string& a, const std::string& b);

const char* standardPlotLayoutLabel(int layoutIndex) {
  static constexpr const char* kLabels[kViewerLayoutChoiceCount] = {
      "Single", "Split 2", "Triple Columns", "Triple 2 + 1", "Quadrants", "Six Views", "Solo"};
  return kLabels[std::clamp(layoutIndex, 0, kViewerLayoutChoiceCount - 1)];
}

int standardPlotLayoutIndexForDisplayRow(int row) {
  static constexpr int kDisplayOrder[kViewerLayoutChoiceCount] = {
      kViewerLayoutSoloIndex, 0, 1, 2, 3, 4, 5};
  return kDisplayOrder[std::clamp(row, 0, kViewerLayoutChoiceCount - 1)];
}

int standardPlotLayoutIndexForName(const std::string& name) {
  for (int i = 0; i < kViewerLayoutChoiceCount; ++i) {
    if (viewerNamesEqualNoCase(name, standardPlotLayoutLabel(i))) return i;
  }
  return -1;
}

bool standardPlotLayoutNameReserved(const std::string& name) {
  return viewerNamesEqualNoCase(name, "Custom") || standardPlotLayoutIndexForName(name) >= 0;
}

int standardPlotLayoutRequiredCount(int layoutIndex) {
  switch (std::clamp(layoutIndex, 0, kViewerLayoutChoiceCount - 1)) {
    case 1: return 2;
    case 2: return 3;
    case 3: return 3;
    case 4: return 4;
    case 5: return 6;
    case kViewerLayoutSoloIndex: return 1;
    case 0:
    default: return 1;
  }
}

void invalidatePlotWindowTransientData(PlotWindowState* window);

PlotWindowRectNorm standardPlotLayoutSlotRect(int layoutIndex, int slotIndex) {
  layoutIndex = std::clamp(layoutIndex, 0, kViewerLayoutChoiceCount - 1);
  slotIndex = std::max(0, slotIndex);
  if (layoutIndex == 1) {
    return {slotIndex == 0 ? 0.0f : 0.5f, 0.0f, 0.5f, 1.0f};
  }
  if (layoutIndex == 2) {
    return {static_cast<float>(std::min(slotIndex, 2)) / 3.0f, 0.0f, 1.0f / 3.0f, 1.0f};
  }
  if (layoutIndex == 3) {
    if (slotIndex == 0) return {0.0f, 0.0f, 2.0f / 3.0f, 1.0f};
    return {2.0f / 3.0f, slotIndex == 1 ? 0.0f : 0.5f, 1.0f / 3.0f, 0.5f};
  }
  if (layoutIndex == 4) {
    const int col = slotIndex % 2;
    const int row = slotIndex / 2;
    return {static_cast<float>(col) * 0.5f, static_cast<float>(row) * 0.5f, 0.5f, 0.5f};
  }
  if (layoutIndex == 5) {
    const int col = slotIndex % 3;
    const int row = slotIndex / 3;
    return {static_cast<float>(col) / 3.0f,
            static_cast<float>(row) / 2.0f,
            1.0f / 3.0f,
            0.5f};
  }
  return {0.0f, 0.0f, 1.0f, 1.0f};
}

std::pair<int, int> standardPlotLayoutPreferredWindowSize(int layoutIndex) {
  switch (std::clamp(layoutIndex, 0, kViewerLayoutChoiceCount - 1)) {
    case 1: return {1120, 640};
    case 2: return {1320, 720};
    case 3: return {1280, 760};
    case 4: return {1280, 900};
    case 5: return {1468, 1030};
    case kViewerLayoutSoloIndex:
    case 0:
    default: return {720, 600};
  }
}

int standardPlotLayoutDefaultPlotModel(int layoutIndex, int slotIndex) {
  if (std::clamp(layoutIndex, 0, kViewerLayoutChoiceCount - 1) == kViewerLayoutSoloIndex) return -1;
  static constexpr int kDefaultSlotModels[6] = {
      ChromaspaceViewer::kPlotModelCube,
      ChromaspaceViewer::kPlotModelHistogram,
      ChromaspaceViewer::kPlotModelSourceSignal,
      ChromaspaceViewer::kPlotModelHsl,
      ChromaspaceViewer::kPlotModelJpConical,
      ChromaspaceViewer::kPlotModelWaveform};
  return kDefaultSlotModels[std::clamp(slotIndex, 0, 5)];
}

void stageViewerWindowPlacement(AppState* app,
                                int width,
                                int height,
                                bool hasPosition = false,
                                int posX = 0,
                                int posY = 0) {
  if (!app) return;
  app->pendingViewerWindowWidth = std::max(320, width);
  app->pendingViewerWindowHeight = std::max(240, height);
  app->pendingViewerWindowPositionValid = hasPosition;
  if (hasPosition) {
    app->pendingViewerWindowPosX = posX;
    app->pendingViewerWindowPosY = posY;
  }
}

void applyDefaultStandardLayoutSlotState(PlotWindowState* window, int layoutIndex, int slotIndex) {
  if (!window) return;
  const int model = standardPlotLayoutDefaultPlotModel(layoutIndex, slotIndex);
  if (model < 0) return;
  const int previousModel = window->viewState.plotModel;
  window->viewState = viewerStateForPlotModel(window->viewState, model);
  if (model == ChromaspaceViewer::kPlotModelWaveform) {
    window->viewState.waveformMode = 1;
  }
  if (model == ChromaspaceViewer::kPlotModelHistogram) {
    window->viewState.histogramMode = 0;
  }
  window->viewState = viewerStateWithModelCapabilities(window->viewState);
  if (window->viewState.plotModel != previousModel) invalidatePlotWindowTransientData(window);
  window->sourceSignalDocked = false;
  window->sourceSignalTemporaryLassoSurface = false;
  window->sourceSignalDockOwnerWindowId = -1;
}

bool plotWindowRectNear(const PlotWindowRectNorm& a, const PlotWindowRectNorm& b) {
  return std::fabs(a.x - b.x) <= 0.015f &&
         std::fabs(a.y - b.y) <= 0.015f &&
         std::fabs(a.w - b.w) <= 0.015f &&
         std::fabs(a.h - b.h) <= 0.015f;
}

int inferStandardPlotLayoutIndexFromWindows(const std::vector<PlotWindowState>& windows) {
  std::vector<const PlotWindowState*> visible;
  visible.reserve(windows.size());
  for (const auto& window : windows) {
    if (plotWindowIsTemporarySourceSignalLassoSurface(window)) continue;
    visible.push_back(&window);
  }
  std::stable_sort(visible.begin(), visible.end(), [](const PlotWindowState* a, const PlotWindowState* b) {
    if (std::fabs(a->rect.y - b->rect.y) > 0.0001f) return a->rect.y < b->rect.y;
    if (std::fabs(a->rect.x - b->rect.x) > 0.0001f) return a->rect.x < b->rect.x;
    return a->windowId < b->windowId;
  });
  for (int layoutIndex = 0; layoutIndex < kViewerLayoutChoiceCount; ++layoutIndex) {
    const int required = standardPlotLayoutRequiredCount(layoutIndex);
    if (static_cast<int>(visible.size()) != required) continue;
    bool matches = true;
    for (int slot = 0; slot < required; ++slot) {
      if (!plotWindowRectNear(visible[static_cast<std::size_t>(slot)]->rect,
                              standardPlotLayoutSlotRect(layoutIndex, slot))) {
        matches = false;
        break;
      }
    }
    if (matches) return layoutIndex;
  }
  return -1;
}

bool plotWindowParticipatesInLayoutSlots(const PlotWindowState& window) {
  return !plotWindowIsTemporarySourceSignalLassoSurface(window);
}

std::vector<int> plotWindowLayoutSlotOrder(const AppState& app) {
  std::vector<int> order;
  order.reserve(app.plotWindows.size());
  for (int i = 0; i < static_cast<int>(app.plotWindows.size()); ++i) {
    if (!plotWindowParticipatesInLayoutSlots(app.plotWindows[static_cast<std::size_t>(i)])) continue;
    order.push_back(i);
  }
  std::stable_sort(order.begin(), order.end(), [&](int ai, int bi) {
    const PlotWindowState& a = app.plotWindows[static_cast<std::size_t>(ai)];
    const PlotWindowState& b = app.plotWindows[static_cast<std::size_t>(bi)];
    if (std::fabs(a.rect.y - b.rect.y) > 0.0001f) return a.rect.y < b.rect.y;
    if (std::fabs(a.rect.x - b.rect.x) > 0.0001f) return a.rect.x < b.rect.x;
    if (std::fabs(a.rect.h - b.rect.h) > 0.0001f) return a.rect.h > b.rect.h;
    if (std::fabs(a.rect.w - b.rect.w) > 0.0001f) return a.rect.w > b.rect.w;
    return a.windowId < b.windowId;
  });
  return order;
}

void invalidatePlotWindowTransientData(PlotWindowState* window) {
  if (!window) return;
  releasePlotWindowGpuCaches(window);
  window->derivedMesh = {};
  window->overlayMesh = {};
  window->derivedBuildKey.clear();
  window->overlayBuildKey.clear();
  window->derivedMeshValid = false;
  window->overlayMeshValid = false;
  window->fitRequested = true;
}

void captureStandardLayoutSlotMemory(AppState* app) {
  if (!app) return;
  snapshotFocusedPlotWindowForPresetSerialization(app);
  const int layoutIndex = std::clamp(app->activeStandardLayoutIndex, 0, kViewerLayoutChoiceCount - 1);
  const std::vector<int> order = plotWindowLayoutSlotOrder(*app);
  const int count = std::min(standardPlotLayoutRequiredCount(layoutIndex),
                             static_cast<int>(order.size()));
  auto& slots = app->standardLayoutSlotMemory[static_cast<std::size_t>(layoutIndex)];
  slots.resize(static_cast<std::size_t>(count));
  for (int i = 0; i < count; ++i) {
    const PlotWindowState& window = app->plotWindows[static_cast<std::size_t>(order[static_cast<std::size_t>(i)])];
    PlotLayoutSlotState slot{};
    slot.valid = true;
    slot.viewState = viewerStateWithModelCapabilities(window.viewState);
    slot.camera = window.camera;
    slots[static_cast<std::size_t>(i)] = slot;
  }
}

void applyLayoutSlotStateToWindow(PlotWindowState* window, const PlotLayoutSlotState& slot) {
  if (!window || !slot.valid) return;
  const int previousModel = window->viewState.plotModel;
  window->viewState = viewerStateWithModelCapabilities(slot.viewState);
  window->camera = slot.camera;
  if (window->viewState.plotModel != previousModel) invalidatePlotWindowTransientData(window);
  window->sourceSignalDocked = false;
  window->sourceSignalTemporaryLassoSurface = false;
  window->sourceSignalDockOwnerWindowId = -1;
}

void applyPlotWindowLayout(AppState* app, int layoutIndex, int windowWidth, int windowHeight) {
  if (!app) return;
  layoutIndex = std::clamp(layoutIndex, 0, kViewerLayoutChoiceCount - 1);
  const int previousFocus = app->focusedPlotWindowId;
  snapshotFocusedPlotWindowForPresetSerialization(app);
  const int required = standardPlotLayoutRequiredCount(layoutIndex);
  if (layoutIndex == kViewerLayoutSoloIndex) {
    if (!viewerNamesEqualNoCase(app->layoutPresetSelection, standardPlotLayoutLabel(kViewerLayoutSoloIndex)) &&
        !app->layoutPresetSelection.empty()) {
      app->layoutPresetBeforeSolo = app->layoutPresetSelection;
    }
    PlotWindowState soloWindow{};
    if (const PlotWindowState* focused = effectiveSettingsPlotWindow(*app)) {
      soloWindow = *focused;
    } else {
      ensureDefaultPlotWindow(app);
      soloWindow = app->plotWindows.front();
    }
    soloWindow.rect = clampedPlotWindowRect(*app,
                                            plotWorkspaceRect(*app, 0.0f, 0.0f, 1.0f, 1.0f, windowHeight),
                                            windowWidth,
                                            windowHeight);
    soloWindow.selected = true;
    soloWindow.sourceSignalDocked = false;
    soloWindow.sourceSignalTemporaryLassoSurface = false;
    soloWindow.sourceSignalDockOwnerWindowId = -1;
    app->plotWindows.clear();
    app->plotWindows.push_back(soloWindow);
    app->focusedPlotWindowId = soloWindow.windowId;
    focusPlotWindowWithoutCapture(app, soloWindow.windowId);
    app->activeStandardLayoutIndex = layoutIndex;
    app->layoutPresetSelection = standardPlotLayoutLabel(layoutIndex);
    app->layoutPresetNameInput.clear();
    const auto [preferredW, preferredH] = standardPlotLayoutPreferredWindowSize(layoutIndex);
    stageViewerWindowPlacement(app, preferredW, preferredH);
    logViewerEvent("Applied plot-window layout: Solo");
    return;
  }
  ensurePlotWindowCount(app, required, windowWidth, windowHeight);
  if (static_cast<int>(app->plotWindows.size()) > required) {
    app->plotWindows.resize(static_cast<std::size_t>(required));
  }
  auto setRect = [&](int index, PlotWindowRectNorm rect) {
    if (index >= 0 && index < static_cast<int>(app->plotWindows.size())) {
      app->plotWindows[static_cast<std::size_t>(index)].rect =
          clampedPlotWindowRect(*app,
                                plotWorkspaceRect(*app, rect.x, rect.y, rect.w, rect.h, windowHeight),
                                windowWidth,
                                windowHeight);
    }
  };
  for (int i = 0; i < required; ++i) {
    applyDefaultStandardLayoutSlotState(&app->plotWindows[static_cast<std::size_t>(i)], layoutIndex, i);
    setRect(i, standardPlotLayoutSlotRect(layoutIndex, i));
  }
  app->activeStandardLayoutIndex = layoutIndex;
  app->layoutPresetSelection = standardPlotLayoutLabel(layoutIndex);
  app->layoutPresetNameInput.clear();
  app->layoutPresetBeforeSolo.clear();
  app->layoutStateBeforeSoloJson.clear();
  const auto [preferredW, preferredH] = standardPlotLayoutPreferredWindowSize(layoutIndex);
  stageViewerWindowPlacement(app, preferredW, preferredH);
  if (plotWindowById(app, previousFocus)) {
    focusPlotWindowWithoutCapture(app, previousFocus);
  } else if (!app->plotWindows.empty()) {
    focusPlotWindowWithoutCapture(app, app->plotWindows.back().windowId);
  }
  logViewerEvent(std::string("Applied plot-window layout: ") +
                 standardPlotLayoutLabel(layoutIndex));
}

void rememberOfxImageLassoSelection(AppState* app, const ResolvedPayload& payload) {
  if (!app || !payloadImageLassoModeEnabled(payload)) return;
  const LassoRegionState state = parseViewerLassoRegionState(payload.lassoData);
  if (state.revision > 0) {
    app->lastObservedOfxImageLassoRevision =
        std::max(app->lastObservedOfxImageLassoRevision, state.revision);
  }
  if (payloadHasImageLassoSelection(payload)) {
    if (app->clearImageLassoRequestedRevision > 0 &&
        state.revision <= app->clearImageLassoBaselineRevision) {
      return;
    }
    app->cachedOfxImageLassoData = payload.lassoData;
    if (app->clearImageLassoRequestedRevision > 0) {
      app->clearImageLassoRequestedRevision = 0;
      app->clearImageLassoBaselineRevision = 0;
    }
    return;
  }
  // A serialized empty lasso carries an explicit reset revision. Do not restore
  // the previous selection over it while the matching empty cloud is arriving.
  if (payload.lassoRegionEmpty && state.revision > 0) {
    app->cachedOfxImageLassoData.clear();
    if (app->clearImageLassoRequestedRevision > 0 &&
        state.revision > app->clearImageLassoBaselineRevision) {
      app->clearImageLassoRequestedRevision = 0;
      app->clearImageLassoBaselineRevision = 0;
    }
  }
}

uint64_t currentKnownOfxImageLassoRevision(const AppState& app) {
  const LassoRegionState cached = parseViewerLassoRegionState(app.cachedOfxImageLassoData);
  return std::max(app.lastObservedOfxImageLassoRevision, cached.revision);
}

void beginPendingImageLassoClear(AppState* app, uint64_t requestRevision) {
  if (!app) return;
  app->clearImageLassoBaselineRevision = currentKnownOfxImageLassoRevision(*app);
  app->clearImageLassoRequestedRevision = requestRevision;
  app->cachedOfxImageLassoData.clear();
}

void applyCachedOfxImageLassoSelection(const AppState& app, ResolvedPayload* payload) {
  if (app.clearImageLassoRequestedRevision > 0) return;
  if (!payload || !payloadImageLassoModeEnabled(*payload) || payloadHasImageLassoSelection(*payload) ||
      app.cachedOfxImageLassoData.empty()) {
    return;
  }
  const LassoRegionState current = parseViewerLassoRegionState(payload->lassoData);
  if (payload->lassoRegionEmpty && current.revision > 0) return;
  const LassoRegionState cached = parseViewerLassoRegionState(app.cachedOfxImageLassoData);
  if (cached.strokes.empty()) return;
  payload->lassoData = app.cachedOfxImageLassoData;
  payload->lassoRegionEmpty = false;
  payload->cloudSettingsKey = cloudSettingsKeyWithoutImageLasso(payload->cloudSettingsKey) +
                              imageLassoSettingsSuffixForData(payload->lassoData);
}

void applyPendingImageLassoResetToResolvedPayload(const AppState& app, ResolvedPayload* payload) {
  if (!payload || app.clearImageLassoRequestedRevision == 0 ||
      !payloadImageLassoModeEnabled(*payload)) {
    return;
  }
  if (payloadHasImageLassoSelection(*payload)) return;
  payload->lassoData =
      serializeViewerLassoRegionState(std::max<uint64_t>(1, app.clearImageLassoBaselineRevision + 1), {});
  payload->lassoRegionEmpty = true;
  payload->cloudSettingsKey = cloudSettingsKeyWithoutImageLasso(payload->cloudSettingsKey) +
                              imageLassoSettingsSuffixForData(payload->lassoData);
}
// Section: viewer lasso ownership
// Source Signal drawing, target-window ownership, pending OFX-clear ordering,
// and payload lasso serialization live here. Mouse callbacks call these helpers;
// source filtering consumes their serialized data in source-derived mesh builders.
bool viewerLassoInteractionEnabled(const AppState& app,
                                   GLFWwindow* window,
                                   double xpos,
                                   double ypos) {
  if (!window || !viewerImageLassoSessionActive(app)) return false;
  int windowWidth = 1;
  int windowHeight = 1;
  glfwGetWindowSize(window, &windowWidth, &windowHeight);
  const PlotWindowState* sourceWindow = nullptr;
  for (auto it = app.plotWindows.rbegin(); it != app.plotWindows.rend(); ++it) {
    if (plotWindowIsSourceSignal(*it) &&
        pointInPlotWindowRect(app, *it, windowWidth, windowHeight, xpos, ypos)) {
      sourceWindow = &(*it);
      break;
    }
  }
  if (!sourceWindow) return false;

  float x0 = 0.0f;
  float y0 = 0.0f;
  float x1 = 0.0f;
  float y1 = 0.0f;
  if (!sourceSignalImageRectForCanvas(app, *sourceWindow, windowWidth, windowHeight, true,
                                      &x0, &y0, &x1, &y1)) {
    return false;
  }
  return xpos >= x0 && xpos <= x1 && ypos >= y0 && ypos <= y1;
}

LassoPointNorm viewerLassoPointFromCursor(const AppState& app,
                                          GLFWwindow* window,
                                          double xpos,
                                          double ypos) {
  int windowWidth = 1;
  int windowHeight = 1;
  glfwGetWindowSize(window, &windowWidth, &windowHeight);
  if (const PlotWindowState* sourceWindow = activeSourceSignalLassoWindow(app)) {
    float x0 = 0.0f;
    float y0 = 0.0f;
    float x1 = 0.0f;
    float y1 = 0.0f;
    if (sourceSignalImageRectForCanvas(app, *sourceWindow, windowWidth, windowHeight, true,
                                       &x0, &y0, &x1, &y1) &&
        x1 > x0 && y1 > y0) {
      return {clampf((static_cast<float>(xpos) - x0) / (x1 - x0), 0.0f, 1.0f),
              clampf((y1 - static_cast<float>(ypos)) / (y1 - y0), 0.0f, 1.0f)};
    }
  }
  const float xNorm = clampf(static_cast<float>(xpos) / static_cast<float>(std::max(1, windowWidth)),
                             0.0f,
                             1.0f);
  const float yNorm = clampf(1.0f - static_cast<float>(ypos) / static_cast<float>(std::max(1, windowHeight)),
                             0.0f,
                             1.0f);
  return {xNorm, yNorm};
}

void rebuildViewerLassoData(AppState* app) {
  if (!app) return;
  app->viewerLassoData =
      serializeViewerLassoRegionState(app->viewerLassoRevision, app->viewerLassoStrokes);
}

void rebuildViewerLassoData(PlotWindowState* window) {
  if (!window) return;
  window->viewerLassoData =
      serializeViewerLassoRegionState(window->viewerLassoRevision, window->viewerLassoStrokes);
}

const std::vector<LassoStroke>* viewerLassoStrokesForActiveSelection(const AppState& app) {
  if (!viewerSourceSelectionsSynced(app)) {
    if (const PlotWindowState* target = activeViewerLassoTargetWindow(app)) {
      return &target->viewerLassoStrokes;
    }
  }
  return &app.viewerLassoStrokes;
}

std::string viewerLassoDataForPlotWindow(const AppState& app, const PlotWindowState* window) {
  if (!viewerSourceSelectionsSynced(app) && window) {
    if (const PlotWindowState* target = activeViewerLassoTargetWindow(app);
        target && target->windowId != window->windowId) {
      return {};
    }
  }
  if (!viewerSourceSelectionsSynced(app) && window) {
    return window->viewerLassoData.empty()
               ? serializeViewerLassoRegionState(std::max<uint64_t>(1, window->viewerLassoRevision), {})
               : window->viewerLassoData;
  }
  return app.viewerLassoData.empty()
             ? serializeViewerLassoRegionState(std::max<uint64_t>(1, app.viewerLassoRevision), {})
             : app.viewerLassoData;
}

bool activeViewerLassoSelectionHasData(const AppState& app) {
  if (!viewerSourceSelectionsSynced(app)) {
    if (const PlotWindowState* target = activeViewerLassoTargetWindow(app)) {
      return !parseViewerLassoRegionState(target->viewerLassoData).strokes.empty();
    }
    return false;
  }
  return !parseViewerLassoRegionState(app.viewerLassoData).strokes.empty();
}

bool plotWindowShouldShowImageLassoStandby(const AppState& app, const PlotWindowState* window) {
  if (!window || app.viewerLassoDrawing || !viewerImageLassoSessionActive(app)) return false;
  const auto state = viewerStateWithModelCapabilities(window->viewState);
  if (!state.volumeSliceLassoRegion || !plotWindowCanOwnViewerLassoSelection(*window)) return false;
  if (viewerSourceSelectionsSynced(app)) {
    return parseViewerLassoRegionState(app.viewerLassoData).strokes.empty();
  }
  const PlotWindowState* target = activeViewerLassoTargetWindow(app);
  if (!target || target->windowId != window->windowId) return false;
  return parseViewerLassoRegionState(target->viewerLassoData).strokes.empty();
}

void bumpViewerLocalStateRevision(AppState* app) {
  if (!app) return;
  app->viewerState.stateRevision = std::max<uint64_t>(app->viewerState.stateRevision + 1, 1);
  app->viewerStateLocalOverride = true;
}

bool appendPointToViewerLassoStroke(LassoStroke* stroke, LassoPointNorm point) {
  if (!stroke) return false;
  if (!stroke->points.empty()) {
    const LassoPointNorm last = stroke->points.back();
    const float dx = point.xNorm - last.xNorm;
    const float dy = point.yNorm - last.yNorm;
    if (dx * dx + dy * dy < 0.000012f) return false;
  }
  stroke->points.push_back(point);
  return true;
}

void beginViewerLassoStroke(AppState* app, GLFWwindow* window, double xpos, double ypos) {
  if (!app || !window) return;
  if (!viewerSourceSelectionsSynced(*app)) activeViewerLassoTargetWindow(app);
  app->viewerLassoDrawing = true;
  app->viewerLassoActiveStroke = LassoStroke{};
  app->viewerLassoActiveStroke.subtract = app->viewerLassoSubtractMode || app->altHeld || app->ctrlHeld;
  appendPointToViewerLassoStroke(&app->viewerLassoActiveStroke,
                                 viewerLassoPointFromCursor(*app, window, xpos, ypos));
  app->leftDown = false;
  app->panMode = false;
  app->rollMode = false;
  app->zoomMode = false;
}

void updateViewerLassoStroke(AppState* app, GLFWwindow* window, double xpos, double ypos) {
  if (!app || !window || !app->viewerLassoDrawing) return;
  if (appendPointToViewerLassoStroke(&app->viewerLassoActiveStroke,
                                     viewerLassoPointFromCursor(*app, window, xpos, ypos))) {
    bumpViewerLocalStateRevision(app);
  }
}

void finishViewerLassoStroke(AppState* app) {
  if (!app || !app->viewerLassoDrawing) return;
  app->viewerLassoDrawing = false;
  bool committedStroke = false;
  if (app->viewerLassoActiveStroke.points.size() >= 3) {
    if (!viewerSourceSelectionsSynced(*app)) {
      if (PlotWindowState* target = activeViewerLassoTargetWindow(app)) {
        target->viewerLassoStrokes.push_back(std::move(app->viewerLassoActiveStroke));
        target->viewerLassoRevision = std::max<uint64_t>(target->viewerLassoRevision + 1, 1);
        target->viewState.stateRevision = std::max<uint64_t>(target->viewState.stateRevision + 1, 1);
        rebuildViewerLassoData(target);
        committedStroke = true;
      } else {
        app->viewerLassoStrokes.push_back(std::move(app->viewerLassoActiveStroke));
        app->viewerLassoRevision = std::max<uint64_t>(app->viewerLassoRevision + 1, 1);
        rebuildViewerLassoData(app);
        committedStroke = true;
      }
    } else {
      app->viewerLassoStrokes.push_back(std::move(app->viewerLassoActiveStroke));
      app->viewerLassoRevision = std::max<uint64_t>(app->viewerLassoRevision + 1, 1);
      rebuildViewerLassoData(app);
      committedStroke = true;
    }
    bumpViewerLocalStateRevision(app);
  }
  app->viewerLassoActiveStroke = LassoStroke{};
  if (committedStroke) queueViewerStateCommand(*app, "reinterpret");
}

void clearAllViewerLassoState(AppState* app) {
  if (!app) return;
  app->viewerLassoDrawing = false;
  app->viewerLassoActiveStroke = LassoStroke{};
  app->viewerLassoStrokes.clear();
  app->viewerLassoRevision = std::max<uint64_t>(app->viewerLassoRevision + 1, 1);
  app->viewerLassoData.clear();
  for (auto& window : app->plotWindows) {
    window.viewerLassoStrokes.clear();
    window.viewerLassoRevision = std::max<uint64_t>(window.viewerLassoRevision + 1, 1);
    window.viewerLassoData.clear();
    window.viewState.stateRevision = std::max<uint64_t>(window.viewState.stateRevision + 1, 1);
  }
  bumpViewerLocalStateRevision(app);
}

void clearActiveViewerLassoSelection(AppState* app) {
  if (!app) return;
  app->viewerLassoDrawing = false;
  app->viewerLassoActiveStroke = LassoStroke{};
  if (!viewerSourceSelectionsSynced(*app)) {
    if (PlotWindowState* target = activeViewerLassoTargetWindow(app)) {
      target->viewerLassoStrokes.clear();
      target->viewerLassoRevision = std::max<uint64_t>(target->viewerLassoRevision + 1, 1);
      target->viewerLassoData.clear();
      target->viewState.stateRevision = std::max<uint64_t>(target->viewState.stateRevision + 1, 1);
      bumpViewerLocalStateRevision(app);
      return;
    }
  }
  app->viewerLassoStrokes.clear();
  app->viewerLassoRevision = std::max<uint64_t>(app->viewerLassoRevision + 1, 1);
  app->viewerLassoData.clear();
  bumpViewerLocalStateRevision(app);
}

bool undoActiveViewerLassoStroke(AppState* app) {
  if (!app || !viewerImageLassoSessionActive(*app)) return false;
  if (app->viewerLassoDrawing) {
    app->viewerLassoDrawing = false;
    app->viewerLassoActiveStroke = LassoStroke{};
    bumpViewerLocalStateRevision(app);
    return true;
  }
  if (!viewerSourceSelectionsSynced(*app)) {
    if (PlotWindowState* target = activeViewerLassoTargetWindow(app)) {
      if (target->viewerLassoStrokes.empty()) return false;
      target->viewerLassoStrokes.pop_back();
      target->viewerLassoRevision = std::max<uint64_t>(target->viewerLassoRevision + 1, 1);
      target->viewState.stateRevision = std::max<uint64_t>(target->viewState.stateRevision + 1, 1);
      rebuildViewerLassoData(target);
      bumpViewerLocalStateRevision(app);
      return true;
    }
    return false;
  }
  if (app->viewerLassoStrokes.empty()) return false;
  app->viewerLassoStrokes.pop_back();
  app->viewerLassoRevision = std::max<uint64_t>(app->viewerLassoRevision + 1, 1);
  rebuildViewerLassoData(app);
  bumpViewerLocalStateRevision(app);
  return true;
}

void clearViewerLassoState(AppState* app) {
  clearAllViewerLassoState(app);
}

