float updateViewerMenuPopoverFade(bool visible, float* alpha, double* lastTime) {
  if (!alpha || !lastTime) return visible ? 1.0f : 0.0f;
  const double now = glfwGetTime();
  const double dt = *lastTime > 0.0 ? std::clamp(now - *lastTime, 0.0, 0.10) : 0.016;
  *lastTime = now;
  const float target = visible ? 1.0f : 0.0f;
  const float step = static_cast<float>(dt) * (visible ? 9.0f : 7.0f);
  if (*alpha < target) {
    *alpha = std::min(target, *alpha + step);
  } else if (*alpha > target) {
    *alpha = std::max(target, *alpha - step);
  }
  return *alpha;
}

PlotMenuRect viewerChoiceMenuWindowRect(const AppState& app, int width, int height) {
  const std::vector<ViewerChoiceMenuItem> items = buildViewerChoiceMenuItems(app);
  if (items.empty()) return {};
  const ViewerUiMetrics metrics = viewerUiMetrics(app);
  const ViewerMenuAction action = viewerMenuActionFromInt(app.viewerMenuChoiceAction);
  const int rowIndex = viewerMenuRowIndexForAction(app, action);
  const PlotMenuRect drawer = plotMenuMainRect(app, width, height);
  PlotMenuRect rowRect{};
  const bool anchoredToCompactPreset =
      action == ViewerMenuAction::LoadUserPreset &&
      app.plotModelMenuVisible &&
      (app.viewerPresetChoiceAnchorCompact || rowIndex < 0);
  const bool anchoredToCompactLayoutPreset =
      action == ViewerMenuAction::LoadLayoutPreset &&
      app.plotModelMenuVisible &&
      (app.layoutPresetChoiceAnchorCompact || rowIndex < 0);
  const bool anchoredToWorkspaceLayoutPreset =
      action == ViewerMenuAction::LoadLayoutPreset &&
      app.layoutPresetChoiceAnchorWorkspace &&
      !app.plotModelMenuVisible;
  const bool anchoredToCursorLayoutPreset =
      action == ViewerMenuAction::LoadLayoutPreset &&
      app.layoutPresetChoiceAnchorCursor &&
      !app.plotModelMenuVisible;
  const bool anchoredToChromaticityHud =
      viewerMenuActionIsChromaticityHudChoice(action) &&
      app.chromaticityHudChoiceAnchor &&
      !app.plotModelMenuVisible;
  if (anchoredToCompactPreset) {
    rowRect = viewerMenuCompactPresetWindowRect(app, width, height);
  } else if (anchoredToCompactLayoutPreset) {
    rowRect = viewerMenuCompactLayoutPresetWindowRect(app, width, height);
  } else if (anchoredToWorkspaceLayoutPreset) {
    rowRect = viewerWorkspaceLayoutPresetWindowRect(app, width, height);
  } else if (anchoredToCursorLayoutPreset) {
    rowRect = {static_cast<float>(app.layoutPresetChoiceAnchorX),
               static_cast<float>(app.layoutPresetChoiceAnchorY),
               static_cast<float>(app.layoutPresetChoiceAnchorX),
               static_cast<float>(app.layoutPresetChoiceAnchorY)};
  } else if (anchoredToChromaticityHud) {
    rowRect = {static_cast<float>(app.chromaticityHudChoiceAnchorX0),
               static_cast<float>(app.chromaticityHudChoiceAnchorY0),
               static_cast<float>(app.chromaticityHudChoiceAnchorX1),
               static_cast<float>(app.chromaticityHudChoiceAnchorY1)};
  } else if (rowIndex >= 0) {
    rowRect = viewerMenuRowWindowRect(app, width, height, rowIndex);
  } else {
    return {};
  }
  if (anchoredToChromaticityHud) {
    const float menuWidth =
        clampFloatingMenuWidth(viewerChoiceMenuNaturalWidth(items) * metrics.textScale * 1.10f,
                               230.0f * metrics.textScale,
                               520.0f * metrics.textScale,
                               width);
    const float naturalHeight =
        kViewerChoiceMenuPad * 2.0f + metrics.choiceRowHeight * static_cast<float>(items.size());
    const float menuHeight = std::min(naturalHeight, std::max(metrics.choiceRowHeight, static_cast<float>(height) - 16.0f));
    const float x0 = clampf(rowRect.x1 - menuWidth,
                            8.0f,
                            std::max(8.0f, static_cast<float>(width) - menuWidth - 8.0f));
    float y0 = rowRect.y0 - 4.0f - menuHeight;
    if (y0 < 8.0f) y0 = rowRect.y1 + 4.0f;
    y0 = clampf(y0, 8.0f, std::max(8.0f, static_cast<float>(height) - menuHeight - 8.0f));
    return {x0, y0, x0 + menuWidth, y0 + menuHeight};
  }
  const float rowsX0 = drawer.x0 + kViewerDrawerPad + kViewerDrawerTabRailWidth + kViewerDrawerPad;
  const float rowsX1 = drawer.x1 - kViewerDrawerPad;
  const float availableWidth = std::max(1.0f, rowsX1 - rowsX0);
  const float menuWidth =
      std::min(availableWidth,
               clampFloatingMenuWidth(viewerChoiceMenuNaturalWidth(items) * metrics.textScale,
                                      128.0f,
                                      360.0f * metrics.textScale,
                                      width));
  const float naturalHeight =
      kViewerChoiceMenuPad * 2.0f + metrics.choiceRowHeight * static_cast<float>(items.size());
  const float x1 = rowsX1;
  const float x0 = x1 - menuWidth;
  const float minY = drawer.y0 + kViewerDrawerHeaderHeight + kViewerDrawerPad;
  const float maxY = drawer.y1 - kViewerDrawerPad;
  const float availableHeight = std::max(kViewerChoiceMenuPad * 2.0f + metrics.choiceRowHeight,
                                         maxY - minY);
  const float menuHeight = std::min(naturalHeight, availableHeight);
  float y0 = (anchoredToCompactPreset || anchoredToCompactLayoutPreset ||
              anchoredToWorkspaceLayoutPreset || anchoredToCursorLayoutPreset)
                 ? rowRect.y1 + 6.0f
                 : rowRect.y1 + 4.0f;
  if (y0 + menuHeight > maxY) y0 = rowRect.y0 - 4.0f - menuHeight;
  y0 = clampf(y0, minY, std::max(minY, maxY - menuHeight));
  if (anchoredToWorkspaceLayoutPreset) {
    const float x0Workspace = clampf(rowRect.x0, 8.0f, std::max(8.0f, static_cast<float>(width) - menuWidth - 8.0f));
    const float y0Workspace = clampf(rowRect.y1 + 6.0f,
                                     8.0f,
                                     std::max(8.0f, static_cast<float>(height) - menuHeight - 8.0f));
    return {x0Workspace, y0Workspace, x0Workspace + menuWidth, y0Workspace + menuHeight};
  }
  if (anchoredToCursorLayoutPreset) {
    const float cursorX = clampf(static_cast<float>(app.layoutPresetChoiceAnchorX),
                                 8.0f,
                                 std::max(8.0f, static_cast<float>(width) - menuWidth - 8.0f));
    const float cursorY = clampf(static_cast<float>(app.layoutPresetChoiceAnchorY),
                                 8.0f,
                                 std::max(8.0f, static_cast<float>(height) - menuHeight - 8.0f));
    return {cursorX, cursorY, cursorX + menuWidth, cursorY + menuHeight};
  }
  if (anchoredToCompactPreset || anchoredToCompactLayoutPreset) {
    const float compactX0 = drawer.x0 + kViewerDrawerPad;
    const float compactX1 = std::min(drawer.x1 - kViewerDrawerPad, compactX0 + menuWidth);
    return {compactX0, y0, compactX1, y0 + menuHeight};
  }
  return {x0, y0, x1, y0 + menuHeight};
}

